-- GENERATO da contenuti/ con npm run contenuti: non modificare a mano.
-- 616 domande, 100 nel nucleo gratuito.
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q1', 'Choose the correct translation for ''Sei mai stato in Brasile?''', '["Are you ever been to Brazil?","Have you ever been to Brazil?","Did you ever went to Brazil?","Have you never been to Brazil?"]', NULL, 1, 'We use Present Perfect (''Have you ever been'') for life experiences.', NULL, 'Grammatica', 'B1', 'Present Perfect', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q2', 'Choose the correct question: ''_____ a table in this room?''', '["Is it","There is","Is there","Are there"]', NULL, 2, '''Is there'' is the correct question form of ''there is'' for singular nouns.', NULL, 'Grammatica', 'A1', 'There is / There are', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q3', 'Which sentence is correct?', '["Did you meet Mr. Smith''s wife?","Did you met Mr. Smith''s wife?","Have you meet Mr. Smith''s wife?","Did you meet the Mr. Smith wife?"]', NULL, 0, 'After ''did'', we use the base form of the verb (''meet'', not ''met'').', NULL, 'Grammatica', 'A2', 'Past Simple', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q4', 'Translate ''Lunedì è il giorno peggiore della settimana.''', '["Monday is the badder day of the week.","Monday is the worst day of the week.","Monday is the worse day of the week.","Monday is the baddest day of the week."]', NULL, 1, 'The superlative of ''bad'' is ''worst''.', NULL, 'Traduzione', 'A2', 'Comparatives and Superlatives', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q5', 'Translate ''Sono stato in Africa nel 2009.''', '["I have been to Africa in 2009.","I went to Africa in 2009.","I was in Africa on 2009.","I go to Africa in 2009."]', NULL, 1, 'With a finished time in the past (''in 2009''), we use the Past Simple (''went'').', NULL, 'Traduzione', 'A2', 'Past Simple', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q6', 'Which sentence correctly compares the two cities?', '["New York is more modern that London.","New York is modener than London.","New York is more modern than London.","New York is the most modern than London."]', NULL, 2, 'We use ''more + adjective + than'' for comparatives with long adjectives.', NULL, 'Grammatica', 'A2', 'Comparatives and Superlatives', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q7', 'Complete the sentence: ''_____ did you meet Mr. Smith?'' - ''At the station.''', '["When","How","Where","Who"]', NULL, 2, '''Where'' is used to ask about a place.', NULL, 'Grammatica', 'A2', 'Past Simple', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q8', 'Translate ''Quante persone ci sono alla festa?''', '["How much people are at the party?","How many peoples are at the party?","How many people are at the party?","How many people is in the party?"]', NULL, 2, '''People'' is plural and countable, so we use ''How many are''.', NULL, 'Traduzione', 'A1', 'Quantifiers', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q9', 'Translate ''Il treno partirà tra 2 minuti.''', '["The train leaves between 2 minutes.","The train will leave in 2 minutes.","The train going to leave on 2 minutes.","The train part in 2 minutes."]', NULL, 1, 'We use ''in'' for future time limits (''in 2 minutes''). ''Will leave'' expresses a future fact.', NULL, 'Traduzione', 'B1', 'Prepositions of Time', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q10', 'Translate ''Ti posso offrire qualcosa da bere?''', '["Can I offer you anything for drink?","Can I offer you something to drink?","Can I offer you somewhat to drink?","Do I can offer you something to drink?"]', NULL, 1, 'The error in the wrong options is ''for drink'': after ''something/anything'' we use the to-infinitive (''something to drink''). In offers ''something'' is the most common choice, but ''anything'' is also correct (''Can I offer you anything to drink?''). ''Somewhat'' means ''a bit'', and ''can'' never takes ''do''.', NULL, 'Traduzione', 'B1', 'Modals of Ability and Permission', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q11', 'Translate ''Francesco lavora per Google.''', '["Francesco work to Google.","Francesco works for Google.","Francesco is working by Google.","Francesco working for Google."]', NULL, 1, 'Third person singular in Present Simple requires an ''s'' (''works''). ''Work for'' is the correct preposition.', NULL, 'Traduzione', 'A1', 'Present Simple', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q12', 'Choose the correct sentence to describe a current action.', '["Look! It''s rain.","Look! It''s raining.","Look! It rains.","Look! It raining."]', NULL, 1, 'Present Continuous (''is raining'') is used for actions happening right now.', NULL, 'Grammatica', 'A2', 'Present Continuous', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q13', 'Choose the correct question:', '["Is there any milk in the fridge?","Are there some milk in the fridge?","Is there a milk in the fridge?","Is there any milks in the fridge?"]', NULL, 0, '''Milk'' is uncountable, so we use ''Is there'' (not ''Are there''), with no ''a'' and no plural -s. ''Any'' is used in questions.', NULL, 'Grammatica', 'A1', 'There is / There are', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q14', 'Translate ''Da quanto tempo studi l''inglese?''', '["How much time do you study English?","Since when you study English?","How long have you studied English?","How long are you studying English?"]', NULL, 2, 'We use Present Perfect (''have you studied'') with ''How long'' for actions starting in the past and continuing now.', NULL, 'Traduzione', 'B1', 'Present Perfect', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q15', 'Translate ''Francesco riesce a parlare bene inglese.''', '["Francesco can to speak English well.","Francesco can speaks English well.","Francesco is able speak English good.","Francesco can speak English well."]', NULL, 3, 'Modal verb ''can'' is followed by the base form without ''to'' (''can speak'').', NULL, 'Traduzione', 'B1', 'Modals of Ability and Permission', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q16', 'Translate ''Con chi è andata?''', '["With who she went?","Who did she go with?","Who did she went with?","Who she went with?"]', NULL, 1, 'In WH- questions, the auxiliary ''did'' is followed by the base verb ''go''. The preposition ''with'' goes at the end.', NULL, 'Traduzione', 'A2', 'Past Simple', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q17', 'Choose the grammatically correct sentence:', '["She gone to the cinema yesterday.","She has went to the cinema yesterday.","She went to the cinema yesterday.","She goes to the cinema yesterday."]', NULL, 2, '''Yesterday'' requires the Past Simple (''went'').', NULL, 'Grammatica', 'A2', 'Past Simple', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q18', 'Complete the sentence: ''There are many people living in Italy who _____ from abroad.''', '["coming","comes","are coming","come"]', NULL, 3, '''People'' is plural, so the relative clause verb is plural (''come'').', NULL, 'Grammatica', 'A2', 'Relative Clauses', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q19', 'Complete the sentence: ''I _____ my husband in 1996.''', '["meet","have met","met","was meeting"]', NULL, 2, 'A specific time in the past (''in 1996'') requires the Past Simple (''met'').', NULL, 'Grammatica', 'A2', 'Past Simple', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q20', 'Complete the sentence: ''This plate is dirty, can I have a clean _____?''', '["a one","one","ones","it"]', NULL, 1, 'We use the pronoun ''one'' to avoid repeating a singular countable noun (''a clean one'' = ''a clean plate''); ''ones'' is plural and ''it'' would mean the same dirty plate.', NULL, 'Grammatica', 'A2', 'Object Pronouns', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q21', 'Complete the sentence: ''By the year 2080, people could _____ on Mars.''', '["to live","be living","living","are living"]', NULL, 1, '''Could'' is a modal and is followed by the bare infinitive (''be''), never by ''to'' or a conjugated verb. ''Could be living'' expresses a possible ongoing situation in the future.', NULL, 'Grammatica', 'B1', 'Modals of Deduction', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q22', 'Complete the sentence: ''How many companies have you worked for _____ you left school?''', '["from","since","for","after"]', NULL, 1, '''Since'' is used with Present Perfect to indicate a starting point in time.', NULL, 'Grammatica', 'B1', 'Present Perfect', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q23', 'Complete the sentence: ''What time _____ your plane take off?''', '["do","is","does","has"]', NULL, 2, 'For scheduled future events, we use Present Simple. ''Plane'' is ''it'', so we use ''does''.', NULL, 'Grammatica', 'B1', 'Present Simple', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q24', 'Complete the sentence: ''When I was ten, I _____ swim across the lake, but now I can''t.''', '["could","can","was able","could to"]', NULL, 0, '''Could'' is the past of ''can'' for a general ability in the past; ''can'' is present, ''was able'' needs ''to'', and modals are never followed by ''to''.', NULL, 'Grammatica', 'B1', 'Modals of Ability and Permission', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q25', 'Combine the sentences correctly: ''I saw Tom this morning. He was waiting at the bus stop.''', '["I saw Tom this morning while he waits at the bus stop.","I saw Tom this morning while he was waiting at the bus stop.","I saw Tom this morning during he was waiting at the bus stop.","I saw Tom this morning waiting to the bus stop."]', NULL, 1, '''While'' introduces the longer background action, so we use the Past Continuous (''while he was waiting''); the Present Simple ''waits'' doesn''t match the past, and ''during'' must be followed by a noun, not a clause.', NULL, 'Grammatica', 'A2', 'Past Continuous', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q26', 'Complete the sentence: ''James can speak English very _____.''', '["good","better","best","well"]', NULL, 3, '''Well'' is the adverb form of ''good'' and modifies the verb ''speak''.', NULL, 'Grammatica', 'B1', 'Adverbs of Manner', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q27', 'Complete the sentence: ''The children want _____ to play with them.''', '["I","that I","me","my"]', NULL, 2, 'After ''want'', we use an object pronoun (''me'') + to-infinitive.', NULL, 'Grammatica', 'A2', 'Object Pronouns', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q28', 'Complete the sentence: ''Is she going with _____ friends?''', '["much","a","some","any of"]', NULL, 2, '''Friends'' is a plural countable noun, so we can use ''some'' (''some friends''); ''much'' is only for uncountable nouns, ''a'' only for singular nouns, and ''any of'' needs ''the/her'' before the noun.', NULL, 'Grammatica', 'A2', 'Quantifiers', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q29', 'Complete the sentence: ''I _____ a new pair of shoes yesterday.''', '["buy","buyed","bought","have bought"]', NULL, 2, '''Yesterday'' indicates Past Simple. The past of ''buy'' is ''bought''.', NULL, 'Grammatica', 'A2', 'Past Simple', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q30', 'Complete the sentence: ''What time does the train leave tomorrow? It _____ at 9.''', '["leave","will leaves","leaving","leaves"]', NULL, 3, 'For a scheduled timetable in the future, we use the Present Simple with -s for ''it'' (''leaves''); after ''will'' the verb never takes -s.', NULL, 'Grammatica', 'B1', 'Present Simple', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q31', 'Choose the correct negative sentence:', '["There isn''t no milk in the fridge.","There isn''t any milk in the fridge.","There is any milk in the fridge.","There aren''t any milk in the fridge."]', NULL, 1, 'We use ''any'' in negative sentences. ''Milk'' is uncountable, so we use ''isn''t''.', NULL, 'Grammatica', 'A1', 'There is / There are', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q32', 'Complete the sentence: ''How long _____ you studied English?''', '["did","do","are","have"]', NULL, 3, 'Present Perfect uses the auxiliary ''have'' + past participle (''studied'').', NULL, 'Grammatica', 'B1', 'Present Perfect', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q33', 'Complete the sentence: ''Look! It _____.''', '["is raining","rains","rain","rained"]', NULL, 0, '''Look!'' implies an action happening right now (Present Continuous).', NULL, 'Grammatica', 'A2', 'Present Continuous', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q34', 'Complete the sentence: ''How many people _____ to the party?''', '["did came","comes","came","comed"]', NULL, 2, 'When the question word (''How many people'') is the subject, we don''t use ''did''. We just use the past verb (''came''); ''come'' is irregular, so ''comed'' does not exist.', NULL, 'Grammatica', 'A2', 'Past Simple', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q35', 'Translate ''Questa è la cosa migliore che io abbia mai mangiato.''', '["This is the better thing I have ever eaten.","This is the best thing I have ever eaten.","This is the goodest thing I have ever eaten.","This is the most good thing I have ever eaten."]', NULL, 1, 'The superlative of ''good'' is irregular: ''the best''. ''Better'' is the comparative, and ''goodest'' / ''most good'' do not exist.', NULL, 'Traduzione', 'A2', 'Comparatives and Superlatives', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q36', 'Translate ''Steven lavora per Microsoft.''', '["Steven works for Microsoft.","Steven work to Microsoft.","Steven works to Microsoft.","Steven working for Microsoft."]', NULL, 0, 'The Present Simple third person singular requires -s (''works''), and a sentence always needs a conjugated verb. The preposition with a company is ''for''.', NULL, 'Traduzione', 'A1', 'Present Simple', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q37', 'Complete the sentence: ''When _____ you meet Mr. Brown?''', '["have","did","were","do"]', NULL, 1, '''When'' asks for a specific past time, so we use Past Simple auxiliary ''did''.', NULL, 'Grammatica', 'A2', 'Past Simple', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q38', 'Complete the sentence: ''John, where do you come _____?''', '["to","by","from","of"]', NULL, 2, 'The phrase to ask about origins is ''Where do you come from?''', NULL, 'Grammatica', 'A1', 'Questions and Origins', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q39', 'Complete the sentence: ''Tom is away. He has been away _____ Monday.''', '["for","since","from","until"]', NULL, 1, '''Since'' is used with a specific point in time (Monday) to show when an action started.', NULL, 'Grammatica', 'B1', 'Present Perfect', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q40', 'Translate ''Non mi è piaciuto il cibo inglese.''', '["I haven''t liked English food.","I wasn''t like English food.","I didn''t like English food.","I don''t liked English food."]', NULL, 2, 'Past Simple negative uses ''didn''t'' + base verb (''like'').', NULL, 'Traduzione', 'A2', 'Past Simple', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q41', 'Complete the sentence: ''Hurry, the bus _____ in 2 minutes.''', '["leaves","left","is leave","leaving"]', NULL, 0, 'We use Present Simple (''leaves'') for timetabled future events.', NULL, 'Grammatica', 'B1', 'Present Simple', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q42', 'Complete the sentence: ''She''s the most beautiful girl I''ve _____ seen.''', '["never","always","ever","just"]', NULL, 2, '''Ever'' is used with Present Perfect to mean ''at any time in my life''.', NULL, 'Grammatica', 'B1', 'Present Perfect', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q43', 'Complete the sentence: ''I _____ to Africa in 2001.''', '["have gone","was going","went","go"]', NULL, 2, 'Past Simple (''went'') is required for a specific finished past time (''in 2001'').', NULL, 'Grammatica', 'A2', 'Past Simple', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q44', 'Translate ''Hai conosciuto la moglie del signor Smith?''', '["Did you met Mr. Smith''s wife?","Have you met Mr. Smith''s wife?","Do you meet Mr. Smith''s wife?","Have you meet Mr. Smith''s wife?"]', NULL, 1, 'Present Perfect (''Have you met'') is used for life experiences when the time is not specified.', NULL, 'Traduzione', 'B1', 'Present Perfect', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q45', 'Translate ''Conosco Luca da quando eravamo bambini.''', '["I have known Luca since we were children.","I know Luca since we were children.","I have known Luca for we were children.","I am knowing Luca since we were children."]', NULL, 0, 'With ''since'' + a starting point, English uses the Present Perfect (''have known'') for a state that is still true; Italian uses the present (''conosco''), but ''I know... since'' is wrong.', NULL, 'Traduzione', 'B1', 'Present Perfect', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q46', 'Translate ''Non mi piace il trucco di Sara.''', '["I don''t like Sara makeup.","I don''t like Sara''s makeup.","I''m not like Sara''s makeup.","I don''t like the makeup of Sara."]', NULL, 1, 'We use the possessive ''s (Sara''s) to show belonging.', NULL, 'Traduzione', 'A1', 'Possessive S', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q47', 'Complete the sentence: ''_____ is a table in the room.''', '["There","It","This","Here"]', NULL, 0, 'We use ''There is'' to express existence.', NULL, 'Grammatica', 'A1', 'There is / There are', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q48', 'Complete the sentence: ''He _____ his homework right now.''', '["doing","does","is doing","do"]', NULL, 2, '''Right now'' indicates Present Continuous (''is doing'').', NULL, 'Grammatica', 'A2', 'Present Continuous', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q49', 'Choose the correct sentence:', '["If it rains, we will stay home.","If it will rain, we stay home.","If it rains, we would stay home.","If it rain, we will stay home."]', NULL, 0, 'First Conditional: If + Present Simple, will + base verb. We don''t use ''will'' in the if-clause, and ''would'' belongs to the Second Conditional.', NULL, 'Grammatica', 'B1', 'First Conditional', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q50', 'Complete the sentence: ''I _____ playing tennis since I was a child.''', '["am","have been","was","had been"]', NULL, 1, '''Since'' + a point in the past requires the Present Perfect Continuous (''have been playing'').', NULL, 'Grammatica', 'B1', 'Present Perfect', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q51', 'Complete the sentence: ''Where _____ your last summer holiday?''', '["did you spend","you spent","did you spent","do you spent"]', NULL, 0, 'Past Simple questions with a question word use ''did'' + subject + base form (''did you spend''); after ''did'' the verb never goes into the past form.', NULL, 'Grammatica', 'A2', 'Past Simple', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q52', 'Choose the correct sentence for comparing two cities:', '["New York is more much modern than London.","New York is much more modern than London.","New York is most modern than London.","New York is much moderner than London."]', NULL, 1, 'To emphasize a comparative, we use ''much'' before the comparative form (''much more modern'').', NULL, 'Grammatica', 'A2', 'Comparatives and Superlatives', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q54', 'Complete the sentence: ''The sun _____ in the east and sets in the west.''', '["rises","is rising","rise","rised"]', NULL, 0, 'We use the Present Simple for general truths and facts; with a third person singular subject the verb takes -s (''rises'').', NULL, 'Grammatica', 'B1', 'Present Simple', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q55', 'Complete the sentence: ''Have you ever _____ to Brazil?''', '["been","gone","go","went"]', NULL, 0, 'We use ''been to'' to mean ''visited and returned''.', NULL, 'Grammatica', 'B1', 'Present Perfect', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q56', 'Complete the sentence: ''Is she _____ with friends?''', '["gone","go","going","goes"]', NULL, 2, 'The auxiliary ''Is'' indicates Present Continuous, which requires the -ing form (''going'').', NULL, 'Grammatica', 'A2', 'Present Continuous', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q57', 'Translate ''Hai mai mangiato sushi?''', '["Have you ever eaten sushi?","Did you ever eat sushi?","Are you ever eat sushi?","Have you never eat sushi?"]', NULL, 0, 'We use Present Perfect (''Have you ever eaten'') for life experiences.', NULL, 'Traduzione', 'B1', 'Present Perfect', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q58', 'Complete the sentence: ''She _____ just finished her homework.''', '["has","have","did","is"]', NULL, 0, '''Just'' is often used with Present Perfect, and ''She'' takes ''has''.', NULL, 'Grammatica', 'B1', 'Present Perfect', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q59', 'Translate ''Non abbiamo ancora visto quel film.''', '["We haven''t seen that movie yet.","We didn''t see that movie yet.","We don''t see that movie yet.","We haven''t saw that movie yet."]', NULL, 0, 'Present perfect negative with ''yet'' for something expected to happen.', NULL, 'Traduzione', 'B1', 'Present Perfect', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q60', 'Complete the sentence: ''_____ you ever flown in a helicopter?''', '["Have","Did","Do","Are"]', NULL, 0, 'Present Perfect is used for asking about life experiences.', NULL, 'Grammatica', 'B1', 'Present Perfect', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q61', 'Translate ''Lui vive qui da dieci anni.''', '["He has lived here for ten years.","He is living here since ten years.","He lived here since ten years.","He have lived here for ten years."]', NULL, 0, 'Italian ''vive qui da'' + a period of time becomes the Present Perfect + ''for'' in English (''has lived here for ten years''), because the state started in the past and continues now. ''Since'' needs a starting point, not a period.', NULL, 'Traduzione', 'B1', 'Present Perfect', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q62', 'Translate ''Ci sono molte macchine per strada oggi.''', '["There are many cars on the street today.","They are many cars on the street today.","There is many cars on the street today.","There have many cars on the street today."]', NULL, 0, 'We use ''There are'' for plural existence.', NULL, 'Traduzione', 'A1', 'There is / There are', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q63', 'Complete the sentence: ''_____ any milk in the fridge?''', '["Is there","Are there","There is","There are"]', NULL, 0, '''Milk'' is uncountable, so we use ''Is there''.', NULL, 'Grammatica', 'A1', 'There is / There are', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q64', 'Translate ''Non c''è nessun problema.''', '["There is no problem.","There isn''t no problem.","There are no problem.","It isn''t a problem."]', NULL, 0, 'Singular negative existence.', NULL, 'Traduzione', 'A1', 'There is / There are', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q65', 'Complete the sentence: ''_____ some apples on the table.''', '["There are","There is","They are","It is"]', NULL, 0, 'Plural affirmative existence.', NULL, 'Grammatica', 'A1', 'There is / There are', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q66', 'Translate ''C''è un cane nel giardino?''', '["Is there a dog in the garden?","Are there a dog in the garden?","There is a dog in the garden?","Does there a dog in the garden?"]', NULL, 0, 'Question form for singular existence.', NULL, 'Traduzione', 'A1', 'There is / There are', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q67', 'Complete the sentence: ''I _____ to the cinema yesterday.''', '["went","go","was going","have gone"]', NULL, 0, 'Past simple for a finished action at a specific time in the past.', NULL, 'Grammatica', 'A2', 'Past Simple', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q68', 'Translate ''Non hanno studiato per l''esame.''', '["They didn''t study for the exam.","They don''t studied for the exam.","They wasn''t study for the exam.","They haven''t study for the exam."]', NULL, 0, 'Past simple negative uses ''didn''t'' + base verb.', NULL, 'Traduzione', 'A2', 'Past Simple', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q69', 'Complete the sentence: ''_____ you see the football match last night?''', '["Did","Do","Have","Were"]', NULL, 0, 'Past simple question uses auxiliary ''did''.', NULL, 'Grammatica', 'A2', 'Past Simple', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q70', 'Translate ''Lei ha comprato un nuovo telefono la settimana scorsa.''', '["She bought a new phone last week.","She buys a new phone last week.","She buyed a new phone last week.","She have bought a new phone last week."]', NULL, 0, 'The Past Simple of the irregular verb ''buy'' is ''bought''; ''buyed'' does not exist, and ''last week'' excludes the Present Perfect.', NULL, 'Traduzione', 'A2', 'Past Simple', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q71', 'Complete the sentence: ''We _____ very tired after the trip.''', '["were","was","did be","have been"]', NULL, 0, 'Past simple of ''to be'' for ''we'' is ''were''.', NULL, 'Grammatica', 'A2', 'Past Simple', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q72', 'Translate ''Quando sei arrivato?''', '["When did you arrive?","When you arrived?","When do you arrive?","When have you arrived?"]', NULL, 0, 'Question word + did + subject + base verb.', NULL, 'Traduzione', 'A2', 'Past Simple', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q73', 'Complete the sentence: ''Please be quiet, I _____.''', '["am working","work","working","am work"]', NULL, 0, 'Action happening right now requires present continuous.', NULL, 'Grammatica', 'A2', 'Present Continuous', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q74', 'Translate ''Cosa stanno facendo?''', '["What are they doing?","What do they do?","What they are doing?","What are they do?"]', NULL, 0, 'Present continuous question format.', NULL, 'Traduzione', 'A2', 'Present Continuous', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q75', 'Complete the sentence: ''She _____ to music at the moment.''', '["is listening","listens","listening","listen"]', NULL, 0, '''At the moment'' indicates an ongoing action.', NULL, 'Grammatica', 'A2', 'Present Continuous', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q76', 'Translate ''Non sto leggendo un libro, sto guardando la TV.''', '["I''m not reading a book, I''m watching TV.","I don''t read a book, I watch TV.","I''m not read a book, I''m watch TV.","I not reading a book, I watching TV."]', NULL, 0, 'Present continuous for current contrasting actions.', NULL, 'Traduzione', 'A2', 'Present Continuous', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q77', 'Complete the sentence: ''_____ it raining outside?''', '["Is","Does","Are","Do"]', NULL, 0, 'Auxiliary ''to be'' is used for present continuous questions.', NULL, 'Grammatica', 'A2', 'Present Continuous', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q78', 'Complete the sentence: ''If you study hard, you _____ the exam.''', '["will pass","pass","would pass","passed"]', NULL, 0, 'First conditional: If + present simple, will + base verb.', NULL, 'Grammatica', 'B1', 'First Conditional', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q79', 'Translate ''Se piove, non andremo in spiaggia.''', '["If it rains, we won''t go to the beach.","If it will rain, we don''t go to the beach.","If it rain, we won''t go to the beach.","If it rains, we didn''t go to the beach."]', NULL, 0, 'First conditional structure.', NULL, 'Traduzione', 'B1', 'First Conditional', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q80', 'Complete the sentence: ''I will call you if I _____ any news.''', '["hear","will hear","heard","hearing"]', NULL, 0, 'The ''if'' clause uses the present simple.', NULL, 'Grammatica', 'B1', 'First Conditional', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q81', 'Translate ''Cosa farai se perdi il treno?''', '["What will you do if you miss the train?","What do you do if you will miss the train?","What would you do if you miss the train?","What will you do if you missed the train?"]', NULL, 0, 'First conditional question.', NULL, 'Traduzione', 'B1', 'First Conditional', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q82', 'Complete the sentence: ''If she _____ invite me, I won''t go to the party.''', '["doesn''t","don''t","won''t","didn''t"]', NULL, 0, 'Negative present simple in the ''if'' clause.', NULL, 'Grammatica', 'B1', 'First Conditional', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q83', 'Translate ''Se non ti sbrighi, faremo tardi.''', '["If you don''t hurry, we will be late.","If you won''t hurry, we are late.","If you aren''t hurry, we will be late.","If you don''t hurry, we would be late."]', NULL, 0, 'First conditional with negative condition.', NULL, 'Traduzione', 'B1', 'First Conditional', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q84', 'Complete the sentence: ''Russia is the _____ country in the world.''', '["largest","larger","most large","more large"]', NULL, 0, 'Superlative of short adjectives adds -est.', NULL, 'Grammatica', 'A2', 'Comparatives and Superlatives', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q85', 'Translate ''L''inglese è più facile del cinese.''', '["English is easier than Chinese.","English is more easy than Chinese.","English is easiest than Chinese.","English is much easy than Chinese."]', NULL, 0, 'Comparative for ''easy'' is ''easier'', followed by ''than''.', NULL, 'Traduzione', 'A2', 'Comparatives and Superlatives', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q86', 'Complete the sentence: ''This book is _____ interesting than the last one.''', '["more","most","much","very"]', NULL, 0, 'Long adjectives use ''more'' for comparative.', NULL, 'Grammatica', 'A2', 'Comparatives and Superlatives', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q87', 'Translate ''È il film peggiore che abbia mai visto.''', '["It''s the worst movie I''ve ever seen.","It''s the worse movie I''ve ever seen.","It''s the baddest movie I''ve ever seen.","It''s the most bad movie I''ve ever seen."]', NULL, 0, 'Superlative of ''bad'' is ''worst''.', NULL, 'Traduzione', 'A2', 'Comparatives and Superlatives', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q88', 'Complete the sentence: ''My brother is much _____ than me.''', '["taller","tall","tallest","more tall"]', NULL, 0, 'Comparative of ''tall'' is ''taller''. ''Much'' emphasizes it.', NULL, 'Grammatica', 'A2', 'Comparatives and Superlatives', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q89', 'Translate ''Questa è la città più costosa d''Europa.''', '["This is the most expensive city in Europe.","This is the more expensive city in Europe.","This is the expensivest city in Europe.","This is most expensive city in Europe."]', NULL, 0, 'Superlative of long adjectives uses ''the most''.', NULL, 'Traduzione', 'A2', 'Comparatives and Superlatives', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q90', 'Complete the sentence: ''I have been studying English _____ three years.''', '["for","since","from","during"]', NULL, 0, '''For'' is used for a duration or period of time.', NULL, 'Grammatica', 'B1', 'Prepositions of Time', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q91', 'Translate ''Lavora in quella banca dal 2015.''', '["He has worked in that bank since 2015.","He works in that bank from 2015.","He worked in that bank since 2015.","He has worked in that bank for 2015."]', NULL, 0, '''Since'' refers to the starting point of an action.', NULL, 'Traduzione', 'B1', 'Prepositions of Time', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q92', 'Complete the sentence: ''She hasn''t eaten anything _____ yesterday morning.''', '["since","for","from","until"]', NULL, 0, '''Yesterday morning'' is a specific point in time, so we use ''since''.', NULL, 'Grammatica', 'B1', 'Prepositions of Time', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q93', 'Translate ''Stiamo aspettando da due ore.''', '["We have been waiting for two hours.","We are waiting since two hours.","We have been waiting since two hours.","We wait for two hours."]', NULL, 0, 'Duration (two hours) requires ''for''.', NULL, 'Traduzione', 'B1', 'Prepositions of Time', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q94', 'Complete the sentence: ''I haven''t seen him _____ a long time.''', '["for","since","during","from"]', NULL, 0, '''A long time'' is a period of time, so we use ''for''; ''since'' needs a starting point (''since Monday''), and ''during''/''from'' don''t work with the Present Perfect here.', NULL, 'Grammatica', 'B1', 'Prepositions of Time', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q95', 'Complete the sentence: ''He usually _____ up at 7 AM.''', '["wakes","wake","is waking","waked"]', NULL, 0, 'Routines require Present Simple, third person adds -s.', NULL, 'Grammatica', 'A1', 'Present Simple', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q96', 'Translate ''I miei genitori non vivono a Londra.''', '["My parents don''t live in London.","My parents doesn''t live in London.","My parents aren''t live in London.","My parents not live in London."]', NULL, 0, 'Plural subject negative uses ''don''t''.', NULL, 'Traduzione', 'A1', 'Present Simple', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q97', 'Complete the sentence: ''_____ she like chocolate?''', '["Does","Do","Is","Has"]', NULL, 0, 'Question auxiliary for third person singular is ''Does''.', NULL, 'Grammatica', 'A1', 'Present Simple', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q98', 'Translate ''Il treno parte alle 8 in punto.''', '["The train leaves at 8 o''clock.","The train leaving at 8 o''clock.","The train leave at 8 o''clock.","The train left at 8 o''clock."]', NULL, 0, 'Scheduled events (timetables) use the Present Simple: ''The train leaves at 8 o''clock.'' A sentence cannot use the -ing form without ''is''.', NULL, 'Traduzione', 'A1', 'Present Simple', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q99', 'Complete the sentence: ''Water _____ at 100 degrees Celsius.''', '["boils","boil","is boiling","boiled"]', NULL, 0, 'General facts use Present Simple.', NULL, 'Grammatica', 'A1', 'Present Simple', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q100', 'Complete the sentence: ''This is my _____ car.'' (The car belongs to my friend)', '["friend''s","friends''","friend","friends"]', NULL, 0, 'Singular possessive adds ''s.', NULL, 'Grammatica', 'A1', 'Possessive S', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q101', 'Translate ''Dov''è il computer di Marco?''', '["Where is Marco''s computer?","Where is the computer of Marco?","Where is Marcos'' computer?","Where is Marco computer?"]', NULL, 0, 'Possessive ''s is preferred for people.', NULL, 'Traduzione', 'A1', 'Possessive S', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q102', 'Complete the sentence: ''Those are my _____ toys.'' (The toys belong to my dogs)', '["dogs''","dog''s","dogs","dog"]', NULL, 0, 'Regular plural nouns just add an apostrophe after the ''s''.', NULL, 'Grammatica', 'A1', 'Possessive S', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q103', 'Translate ''La borsa di Sarah è rossa.''', '["Sarah''s bag is red.","The bag of Sarah is red.","Sarahs bag is red.","Sarah'' bag is red."]', NULL, 0, 'Possessive ''s shows ownership.', NULL, 'Traduzione', 'A1', 'Possessive S', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q104', 'Complete the sentence: ''We went to my _____ house yesterday.'' (The house belongs to my parents)', '["parents''","parent''s","parents","parent"]', NULL, 0, '''Parents'' is a regular plural ending in -s, so the possessive adds only an apostrophe at the end: ''my parents'' house''. ''Parent''s'' would mean only one parent.', NULL, 'Grammatica', 'A1', 'Possessive S', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q105', 'Complete the sentence: ''How _____ milk is left?''', '["much","many","a lot of","any"]', NULL, 0, '''Milk'' is uncountable, so we use ''much''.', NULL, 'Grammatica', 'A1', 'Quantifiers', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q106', 'Translate ''Non ho molti amici.''', '["I don''t have many friends.","I don''t have much friends.","I don''t have a lot friends.","I don''t have many friend."]', NULL, 0, '''Friends'' is a plural countable noun, so we use ''many'' in negative sentences, and the noun must stay plural after ''many''.', NULL, 'Traduzione', 'A1', 'Quantifiers', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q107', 'Complete the sentence: ''There are _____ people at the concert.''', '["a lot of","much","a lot","many of"]', NULL, 0, 'We use ''a lot of'' for large quantities in affirmative sentences.', NULL, 'Grammatica', 'A1', 'Quantifiers', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q108', 'Translate ''Quanto zucchero vuoi nel caffè?''', '["How much sugar do you want in your coffee?","How many sugar do you want in your coffee?","How much of sugar do you want in your coffee?","What much sugar do you want in your coffee?"]', NULL, 0, 'Sugar is uncountable, so ''How much''.', NULL, 'Traduzione', 'A1', 'Quantifiers', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q109', 'Complete the sentence: ''She has very _____ free time these days.''', '["little","few","a few","many"]', NULL, 0, '''Time'' is uncountable, so we use ''little'' (''very little free time'' = not much time); ''few'', ''a few'' and ''many'' are only used with plural countable nouns.', NULL, 'Grammatica', 'A1', 'Quantifiers', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q110', 'Translate ''Ci sono troppe macchine in questa città.''', '["There are too many cars in this city.","There is too much cars in this city.","There are too much cars in this city.","There are very many cars in this city."]', NULL, 0, '''Cars'' is countable, so ''too many''.', NULL, 'Traduzione', 'A1', 'Quantifiers', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q111', 'Complete the sentence: ''Where _____ you born?''', '["were","was","are","did"]', NULL, 0, 'Past of ''to be'' for ''you'' is ''were''.', NULL, 'Grammatica', 'A1', 'Questions and Origins', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q112', 'Translate ''Da dove viene tuo fratello?''', '["Where does your brother come from?","Where do your brother come from?","Where is your brother come from?","Where does your brother comes from?"]', NULL, 0, 'Third person singular uses ''does'' auxiliary.', NULL, 'Traduzione', 'A1', 'Questions and Origins', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q113', 'Complete the sentence: ''_____ country are you from?''', '["Which","Whose","Where","How"]', NULL, 0, '''Which country'' asks for one item from a set of possible countries (''What country'' is also used). ''Where'' and ''How'' cannot be followed directly by a noun like ''country'', and ''Whose'' asks about possession.', NULL, 'Grammatica', 'A1', 'Questions and Origins', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q114', 'Translate ''Loro sono spagnoli?''', '["Are they Spanish?","Are they Spain?","Do they Spanish?","Is they Spanish?"]', NULL, 0, 'Simple ''to be'' question.', NULL, 'Traduzione', 'A1', 'Questions and Origins', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q115', 'Complete the sentence: ''_____ is the capital of Italy?''', '["What","Where","Which","Who"]', NULL, 0, '''What'' asks for specific information.', NULL, 'Grammatica', 'A1', 'Questions and Origins', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q116', 'Translate ''Di dov''è Maria?''', '["Where is Maria from?","Where does Maria from?","From where is Maria?","Where Maria is from?"]', NULL, 0, 'Standard phrasing for asking origins.', NULL, 'Traduzione', 'A1', 'Questions and Origins', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q117', 'Translate ''Questo è il libro più lungo che abbia mai letto.''', '["This is the longest book I have ever read.","This is the most long book I have ever read.","This is the longer book I have ever read.","This is longest book I have ever read."]', NULL, 0, 'Superlative of short adjectives takes -est.', NULL, 'Traduzione', 'A2', 'Comparatives and Superlatives', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q118', 'Complete: ''My car is _____ than yours.''', '["faster","more fast","fastest","the fastest"]', NULL, 0, 'Comparative of fast is faster.', NULL, 'Grammatica', 'A2', 'Comparatives and Superlatives', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q119', 'Translate ''Oggi è molto più caldo di ieri.''', '["Today is much hotter than yesterday.","Today is much more hot than yesterday.","Today is very hotter than yesterday.","Today is hotter that yesterday."]', NULL, 0, '''much'' emphasizes the comparative ''hotter''.', NULL, 'Traduzione', 'A2', 'Comparatives and Superlatives', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q120', 'Complete: ''She is the _____ student in the class.''', '["best","better","most good","goodest"]', NULL, 0, 'Irregular superlative of good is best.', NULL, 'Grammatica', 'A2', 'Comparatives and Superlatives', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q121', 'Translate ''Sua sorella è meno socievole di lui.''', '["His sister is less outgoing than him.","His sister is least outgoing than him.","His sister is not outgoing than him.","His sister is minor outgoing than him."]', NULL, 0, 'Less + adjective + than is used for inferior comparatives.', NULL, 'Traduzione', 'A2', 'Comparatives and Superlatives', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q122', 'Complete: ''This exercise is _____ difficult than the previous one.''', '["more","much","most","very"]', NULL, 0, 'Long adjectives use ''more'' for comparative.', NULL, 'Grammatica', 'A2', 'Comparatives and Superlatives', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q123', 'Translate ''Questo è il posto meno costoso in città.''', '["This is the least expensive place in town.","This is the less expensive place in town.","This is the not expensive place in town.","This is the most cheap place in town."]', NULL, 0, 'Superlative of inferiority is ''the least''.', NULL, 'Traduzione', 'A2', 'Comparatives and Superlatives', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q124', 'Complete: ''He is _____ taller than his brother.''', '["slightly","a little of","few","small"]', NULL, 0, 'You can modify comparatives with words like slightly, much, a lot.', NULL, 'Grammatica', 'A2', 'Comparatives and Superlatives', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q125', 'Complete: ''If I have time, I _____ you.''', '["will help","help","would help","helped"]', NULL, 0, 'First conditional: if + present, will + base verb.', NULL, 'Grammatica', 'B1', 'First Conditional', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q126', 'Translate ''Se lei studierà, passerà il test.''', '["If she studies, she will pass the test.","If she will study, she will pass the test.","If she study, she will pass the test.","If she studied, she will pass the test."]', NULL, 0, 'Present simple in the if clause, will in the main clause.', NULL, 'Traduzione', 'B1', 'First Conditional', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q127', 'Complete: ''We won''t go to the park if it _____.''', '["rains","will rain","rain","raining"]', NULL, 0, 'If clause uses present simple.', NULL, 'Grammatica', 'B1', 'First Conditional', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q128', 'Translate ''Cosa dirai se lui ti chiamerà?''', '["What will you say if he calls you?","What do you say if he will call you?","What will you say if he will call you?","What would you say if he calls you?"]', NULL, 0, 'Question form: Wh- word + will + subject + verb + if + present simple.', NULL, 'Traduzione', 'B1', 'First Conditional', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q129', 'Complete: ''If they don''t hurry, they _____ the bus.''', '["will miss","miss","would miss","missed"]', NULL, 0, 'Main clause uses will.', NULL, 'Grammatica', 'B1', 'First Conditional', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q130', 'Translate ''Se non mi aiuti, non finirò il progetto.''', '["If you don''t help me, I won''t finish the project.","If you won''t help me, I don''t finish the project.","If you not help me, I won''t finish the project.","If you didn''t help me, I won''t finish the project."]', NULL, 0, 'Negative present simple in if clause, won''t in main clause.', NULL, 'Traduzione', 'B1', 'First Conditional', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q131', 'Complete: ''If she _____ the job, she will move to London.''', '["gets","get","will get","got"]', NULL, 0, 'Third person singular needs ''s'' in present simple.', NULL, 'Grammatica', 'B1', 'First Conditional', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q132', 'Translate ''Gli parlerò se lo vedo.''', '["I will talk to him if I see him.","I talk to him if I will see him.","I will talk to him if I will see him.","I would talk to him if I see him."]', NULL, 0, 'Will in main clause, present in if clause.', NULL, 'Traduzione', 'B1', 'First Conditional', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q133', 'Complete: ''Unless you _____, you won''t succeed.''', '["try","will try","don''t try","tried"]', NULL, 0, 'Unless means ''if not'', so it''s followed by an affirmative verb.', NULL, 'Grammatica', 'B1', 'First Conditional', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q134', 'Translate ''A meno che non piova, andremo a fare una passeggiata.''', '["Unless it rains, we will go for a walk.","Unless it doesn''t rain, we will go for a walk.","If it unless rains, we will go for a walk.","Unless it will rain, we will go for a walk."]', NULL, 0, 'Unless is followed by affirmative present simple.', NULL, 'Traduzione', 'B1', 'First Conditional', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q135', 'Complete: ''I will buy that car if it _____ too expensive.''', '["isn''t","won''t be","doesn''t be","aren''t"]', NULL, 0, 'Verb ''to be'' in present simple negative for third person singular.', NULL, 'Grammatica', 'B1', 'First Conditional', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q136', 'Complete: ''I usually go to bed _____ 11 PM.''', '["at","in","on","to"]', NULL, 0, 'We use ''at'' with clock times (''at 11 PM''); ''in'' is for months, years and parts of the day, and ''on'' for days and dates.', NULL, 'Grammatica', 'A1', 'Prepositions of Time', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q137', 'Translate ''Non mi piace il caffè.''', '["I don''t like coffee.","I''m not like coffee.","I doesn''t like coffee.","I not like coffee."]', NULL, 0, 'Present simple negative for I/you/we/they uses ''don''t''.', NULL, 'Traduzione', 'A1', 'Present Simple', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q138', 'Complete: ''They _____ to Paris next weekend.''', '["are going","go","went","have gone"]', NULL, 0, 'Present continuous can be used for arranged future plans.', NULL, 'Grammatica', 'A2', 'Present Continuous', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q139', 'Translate ''Posso aiutarti?''', '["Can I help you?","Do I can help you?","Am I help you?","May I helping you?"]', NULL, 0, 'Modal verbs like ''can'' form questions by inversion (''Can I help you?'') without ''do'', and they are followed by the base form of the verb.', NULL, 'Traduzione', 'A1', 'Modals of Ability and Permission', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q140', 'Complete: ''She is interested in _____ Spanish.''', '["learning","to learn","learn","learned"]', NULL, 0, 'After a preposition (''interested in'') a verb must take the -ing form (gerund): ''interested in learning'', never the infinitive.', NULL, 'Grammatica', 'B1', 'Gerunds vs Infinitives', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q141', 'Translate ''Dobbiamo andare ora.''', '["We must go now.","We have go now.","We are must go now.","We need going now."]', NULL, 0, '''Must'' is followed by the base form of the verb.', NULL, 'Traduzione', 'A2', 'Modals of Obligation and Advice', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q142', 'Complete: ''I look forward _____ from you soon.''', '["to hearing","to hear","hearing","hear"]', NULL, 0, '''Look forward to'' is followed by the -ing form (gerund).', NULL, 'Grammatica', 'B1', 'Gerunds vs Infinitives', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q143', 'Translate ''Ero molto stanco ieri sera.''', '["I was very tired last night.","I am very tired last night.","I had very tired last night.","I were very tired last night."]', NULL, 0, 'Past simple of ''to be'' for ''I'' is ''was''.', NULL, 'Traduzione', 'A1', 'Past Simple', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q144', 'Complete: ''This is the book _____ I borrowed from the library.''', '["which","who","where","what"]', NULL, 0, 'Relative pronoun ''which'' or ''that'' is used for things.', NULL, 'Grammatica', 'B1', 'Relative Clauses', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q145', 'Translate ''Lei sa nuotare molto bene.''', '["She can swim very well.","She can swims very well.","She knows swim very well.","She knows to swim very well."]', NULL, 0, 'Ability is expressed with ''can'' + base verb (''can swim''); ''can'' never takes -s, and ''sapere fare qualcosa'' is not ''know (to) do'' in English.', NULL, 'Traduzione', 'A1', 'Modals of Ability and Permission', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q146', 'Complete: ''You _____ smoke in the hospital.''', '["mustn''t","don''t have to","needn''t","aren''t"]', NULL, 0, '''Mustn''t'' expresses prohibition.', NULL, 'Grammatica', 'A2', 'Modals of Obligation and Advice', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q147', 'Translate ''Non ho abbastanza soldi.''', '["I don''t have enough money.","I have not enough money.","I don''t have money enough.","I don''t have enough of money."]', NULL, 0, 'In the negative we use ''don''t have'', and ''enough'' goes directly before a noun (''enough money''), without ''of''.', NULL, 'Traduzione', 'A2', 'Quantifiers', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q148', 'Complete: ''That is _____ jacket.'' (The jacket belongs to Tom)', '["Tom''s","Toms''","Tom","Toms"]', NULL, 0, 'Add ''s to singular names.', NULL, 'Grammatica', 'A1', 'Possessive S', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q149', 'Translate ''La casa dei miei nonni è grande.''', '["My grandparents'' house is big.","My grandparent''s house is big.","The house of my grandparents is big.","My grandparents house is big."]', NULL, 0, 'Plural nouns ending in -s just take an apostrophe.', NULL, 'Traduzione', 'A1', 'Possessive S', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q150', 'Complete: ''I love _____ new song.'' (The song of the band)', '["the band''s","the bands''","the band","the bands"]', NULL, 0, 'Singular noun ''band'' takes ''s.', NULL, 'Grammatica', 'A1', 'Possessive S', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q151', 'Translate ''I giocattoli dei bambini sono sparsi ovunque.''', '["The children''s toys are scattered everywhere.","The childrens'' toys are scattered everywhere.","The children toys are scattered everywhere.","The toys of children are scattered everywhere."]', NULL, 0, '''Children'' is an irregular plural not ending in -s, so its possessive is ''s (''children''s''); ''sparsi'' is ''scattered''.', NULL, 'Traduzione', 'A1', 'Possessive S', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q152', 'Complete: ''This is _____ desk.'' (The desk belongs to the boss)', '["the boss''s","the boss''","the boss","the bosses"]', NULL, 0, 'Singular nouns ending in -s usually take ''s.', NULL, 'Grammatica', 'A1', 'Possessive S', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q153', 'Translate ''La macchina di James è blu.''', '["James''s car is blue.","James car is blue.","The car of James is blue.","Jame''s car is blue."]', NULL, 0, 'Names ending in -s can take ''s or just an apostrophe. ''James''s'' is common.', NULL, 'Traduzione', 'A1', 'Possessive S', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q154', 'Complete: ''I went to the _____.'' (The shop of the baker)', '["baker''s","bakers''","baker","bakers"]', NULL, 0, 'Possessive form is often used alone for shops/businesses.', NULL, 'Grammatica', 'A1', 'Possessive S', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q155', 'Translate ''È il compleanno di mia madre.''', '["It''s my mother''s birthday.","It''s the birthday of my mother.","It''s my mothers birthday.","It''s my mother birthday."]', NULL, 0, 'Possessive ''s for people.', NULL, 'Traduzione', 'A1', 'Possessive S', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q156', 'Complete: ''We are meeting at _____.'' (The house of Paul)', '["Paul''s","Pauls''","Paul","Pauls"]', NULL, 0, 'Possessive form is often used alone for people''s houses.', NULL, 'Grammatica', 'A1', 'Possessive S', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q157', 'Translate ''Le scarpe da donna sono al secondo piano.''', '["Women''s shoes are on the second floor.","Womens'' shoes are on the second floor.","Woman''s shoes are on the second floor.","Women shoes are on the second floor."]', NULL, 0, 'Irregular plural ''women'' takes ''s.', NULL, 'Traduzione', 'A1', 'Possessive S', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q158', 'Complete: ''The _____ room is down the hall.'' (The room for teachers)', '["teachers''","teacher''s","teachers","teacher"]', NULL, 0, 'Plural ''teachers'' takes an apostrophe after the s.', NULL, 'Grammatica', 'A1', 'Possessive S', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q159', 'Translate ''Hai visto le chiavi di Anna?''', '["Have you seen Anna''s keys?","Have you seen the keys of Anna?","Have you seen Annas keys?","Have you seen Anna keys?"]', NULL, 0, 'Singular name takes ''s.', NULL, 'Traduzione', 'A1', 'Possessive S', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q160', 'Complete: ''I have known him _____ 2010.''', '["since","for","from","in"]', NULL, 0, '''Since'' indicates a specific starting point in the past.', NULL, 'Grammatica', 'B1', 'Prepositions of Time', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q161', 'Translate ''Lavorano qui da molti anni.''', '["They have worked here for many years.","They work here since many years.","They have worked here since many years.","They work here for many years."]', NULL, 0, '''For'' is used for a duration.', NULL, 'Traduzione', 'B1', 'Prepositions of Time', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q162', 'Complete: ''They _____ tennis right now.''', '["are playing","play","playing","is playing"]', NULL, 0, 'Actions happening now use present continuous.', NULL, 'Grammatica', 'A2', 'Present Continuous', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q163', 'Translate ''Perché stai piangendo?''', '["Why are you crying?","Why do you cry?","Why you are crying?","Why you cry?"]', NULL, 0, 'Question word + are + subject + verb-ing.', NULL, 'Traduzione', 'A2', 'Present Continuous', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q164', 'Complete: ''I _____ to the doctor tomorrow afternoon.''', '["am going","go","went","going"]', NULL, 0, 'Present continuous is used for arranged future plans.', NULL, 'Grammatica', 'A2', 'Present Continuous', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q165', 'Translate ''Il sole sta splendendo.''', '["The sun is shining.","The sun shines.","The sun shining.","The sun are shining."]', NULL, 0, 'Action happening now.', NULL, 'Traduzione', 'A2', 'Present Continuous', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q166', 'Complete: ''Look! The bus _____.''', '["is coming","comes","coming","come"]', NULL, 0, '''Look!'' indicates an action happening at the moment.', NULL, 'Grammatica', 'A2', 'Present Continuous', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q167', 'Translate ''Non stiamo usando il computer adesso.''', '["We aren''t using the computer right now.","We don''t use the computer right now.","We not using the computer right now.","We isn''t using the computer right now."]', NULL, 0, 'Negative present continuous.', NULL, 'Traduzione', 'A2', 'Present Continuous', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q168', 'Complete: ''_____ he watching TV?''', '["Is","Does","Are","Do"]', NULL, 0, 'Auxiliary ''to be'' for third person singular is ''is''.', NULL, 'Grammatica', 'A2', 'Present Continuous', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q169', 'Translate ''Sto cercando le mie chiavi.''', '["I am looking for my keys.","I look for my keys.","I am searching my keys.","I looking for my keys."]', NULL, 0, '''Look for'' means ''cercare'', present continuous for current action.', NULL, 'Traduzione', 'A2', 'Present Continuous', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q170', 'Complete: ''The kids _____ sleeping in their room.''', '["are","is","do","does"]', NULL, 0, 'Plural subject ''kids'' takes ''are''.', NULL, 'Grammatica', 'A2', 'Present Continuous', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q171', 'Complete: ''I have _____ finished my dinner.''', '["already","yet","ever","since"]', NULL, 0, '''Already'' is used in affirmative sentences for completed actions.', NULL, 'Grammatica', 'B1', 'Present Perfect', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q172', 'Translate ''È la prima volta che guido una macchina.''', '["It''s the first time I have driven a car.","It''s the first time I drive a car.","It''s the first time I drove a car.","It''s the first time I am driving a car."]', NULL, 0, '''First time'' expressions use the present perfect.', NULL, 'Traduzione', 'B1', 'Present Perfect', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q173', 'Complete: ''She _____ coffee every morning.''', '["drinks","drink","is drinking","drank"]', NULL, 0, 'Habits use present simple. Third person adds -s.', NULL, 'Grammatica', 'A1', 'Present Simple', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q174', 'Translate ''Io lavoro in un ospedale.''', '["I work in a hospital.","I am working in a hospital.","I works in a hospital.","I work to a hospital."]', NULL, 0, 'Permanent situations use present simple.', NULL, 'Traduzione', 'A1', 'Present Simple', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q175', 'Complete: ''They _____ play tennis on Sundays.''', '["don''t","doesn''t","aren''t","isn''t"]', NULL, 0, 'Plural negative present simple uses ''don''t''.', NULL, 'Grammatica', 'A1', 'Present Simple', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q176', 'Translate ''Lui non capisce la domanda.''', '["He doesn''t understand the question.","He don''t understand the question.","He isn''t understand the question.","He not understands the question."]', NULL, 0, 'Third person singular negative uses ''doesn''t''.', NULL, 'Traduzione', 'A1', 'Present Simple', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q177', 'Complete: ''_____ you speak English?''', '["Do","Are","Does","Is"]', NULL, 0, 'Question auxiliary for ''you'' in present simple is ''do''.', NULL, 'Grammatica', 'A1', 'Present Simple', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q178', 'Translate ''Cosa significa questa parola?''', '["What does this word mean?","What means this word?","What do this word mean?","What is meaning this word?"]', NULL, 0, 'Question uses ''does'' for third person singular (''this word'').', NULL, 'Traduzione', 'A1', 'Present Simple', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q179', 'Complete: ''The sun _____ in the east.''', '["rises","rise","is rising","rose"]', NULL, 0, 'Universal facts use present simple.', NULL, 'Grammatica', 'A1', 'Present Simple', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q180', 'Translate ''Quante volte vai in palestra?''', '["How often do you go to the gym?","How often you go to the gym?","How much time do you go to the gym?","How many times you go to the gym?"]', NULL, 0, '''How often'' asks about frequency.', NULL, 'Traduzione', 'A1', 'Present Simple', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q181', 'Complete: ''My brother never _____ his room.''', '["cleans","clean","is cleaning","cleaned"]', NULL, 0, 'Adverbs of frequency are used with present simple.', NULL, 'Grammatica', 'A1', 'Present Simple', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q182', 'Translate ''Lei ha due gatti e un cane.''', '["She has two cats and a dog.","She have two cats and a dog.","She is having two cats and a dog.","She got two cats and a dog."]', NULL, 0, 'Third person singular of ''have'' is ''has''.', NULL, 'Traduzione', 'A1', 'Present Simple', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q183', 'Complete: ''We _____ like spicy food.''', '["don''t","doesn''t","not","aren''t"]', NULL, 0, 'Negative present simple for ''we''.', NULL, 'Grammatica', 'A1', 'Present Simple', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q184', 'Translate ''Il film inizia alle 20:30.''', '["The movie starts at 8:30 PM.","The movie is starting at 8:30 PM.","The movie start at 8:30 PM.","The movie will starting at 8:30 PM."]', NULL, 0, 'Timetables use present simple.', NULL, 'Traduzione', 'A1', 'Present Simple', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q185', 'Complete: ''Does he _____ in London?''', '["live","lives","living","lived"]', NULL, 0, 'After ''does'', use the base form of the verb.', NULL, 'Grammatica', 'A1', 'Present Simple', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q186', 'Complete: ''I have _____ money in my pocket.''', '["some","any","many","few"]', NULL, 0, 'Affirmative uncountable noun uses ''some''.', NULL, 'Grammatica', 'A1', 'Quantifiers', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q187', 'Translate ''Non ci sono mele.''', '["There aren''t any apples.","There aren''t some apples.","There aren''t no apples.","There are any apples."]', NULL, 0, 'Negative countable uses ''any''.', NULL, 'Traduzione', 'A1', 'Quantifiers', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q188', 'Complete: ''Do you have _____ questions?''', '["any","some","much","little"]', NULL, 0, 'Questions generally use ''any''.', NULL, 'Grammatica', 'A1', 'Quantifiers', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q189', 'Translate ''Vorresti del tè?''', '["Would you like some tea?","Would you like any tea?","Do you like some tea?","Would you like much tea?"]', NULL, 0, 'Offers use ''some'', not ''any''.', NULL, 'Traduzione', 'A1', 'Quantifiers', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q190', 'Complete: ''There are only a _____ students in the class.''', '["few","little","much","many"]', NULL, 0, '''Students'' is countable, so ''a few''.', NULL, 'Grammatica', 'A1', 'Quantifiers', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q191', 'Translate ''Ho pochissimo tempo.''', '["I have very little time.","I have very few time.","I have much little time.","I have very small time."]', NULL, 0, '''Time'' is uncountable, so ''little''.', NULL, 'Traduzione', 'A1', 'Quantifiers', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q192', 'Complete: ''She reads a _____ of books.''', '["lot","many","much","some"]', NULL, 0, 'The phrase is ''a lot of''.', NULL, 'Grammatica', 'A1', 'Quantifiers', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q193', 'Translate ''Abbiamo mangiato troppa pizza.''', '["We ate too much pizza.","We ate too many pizza.","We ate very much pizza.","We ate a lot pizza."]', NULL, 0, '''Pizza'' in general is uncountable, so ''too much''.', NULL, 'Traduzione', 'A1', 'Quantifiers', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q194', 'Complete: ''How _____ apples do you want?''', '["many","much","some","any"]', NULL, 0, '''Apples'' is countable, so ''How many''.', NULL, 'Grammatica', 'A1', 'Quantifiers', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q195', 'Translate ''Non abbiamo comprato niente.''', '["We didn''t buy anything.","We bought anything.","We didn''t buy nothing.","We didn''t buy some."]', NULL, 0, 'Negative sentence requires ''anything''.', NULL, 'Traduzione', 'A1', 'Quantifiers', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q196', 'Complete: ''Is there _____ good on TV?''', '["anything","something","nothing","everything"]', NULL, 0, 'Questions generally use ''anything''.', NULL, 'Grammatica', 'A1', 'Quantifiers', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q197', 'Complete: ''_____ is that man?''', '["Who","What","Which","Where"]', NULL, 0, 'Asking for a person''s identity requires ''Who''.', NULL, 'Grammatica', 'A1', 'Questions and Origins', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q198', 'Translate ''Perché sei in ritardo?''', '["Why are you late?","Because are you late?","Why you are late?","Why do you late?"]', NULL, 0, 'Asking for a reason requires ''Why''.', NULL, 'Traduzione', 'A1', 'Questions and Origins', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q199', 'Complete: ''_____ old are you?''', '["How","What","Who","Which"]', NULL, 0, 'Asking about age uses ''How old''.', NULL, 'Grammatica', 'A1', 'Questions and Origins', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q200', 'Translate ''Quando è il tuo compleanno?''', '["When is your birthday?","Where is your birthday?","What is your birthday?","How is your birthday?"]', NULL, 0, 'Asking for time/date requires ''When''.', NULL, 'Traduzione', 'A1', 'Questions and Origins', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q201', 'Complete: ''_____ do you live?''', '["Where","What","How","When"]', NULL, 0, 'Asking for a place requires ''Where''.', NULL, 'Grammatica', 'A1', 'Questions and Origins', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q202', 'Translate ''Come vai al lavoro?''', '["How do you go to work?","What do you go to work?","Where do you go to work?","Why do you go to work?"]', NULL, 0, 'Asking for method/manner requires ''How''.', NULL, 'Traduzione', 'A1', 'Questions and Origins', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q203', 'Complete: ''_____ is your favorite color?''', '["What","Whose","Who","How"]', NULL, 0, 'We use ''What'' to ask about a general preference (''What is your favorite color?''); ''Whose'' asks about possession, ''Who'' about people and ''How'' about manner.', NULL, 'Grammatica', 'A1', 'Questions and Origins', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q204', 'Translate ''Di chi è questa borsa?''', '["Whose bag is this?","Who bag is this?","Which bag is this?","What bag is this?"]', NULL, 0, 'Asking for possession requires ''Whose''.', NULL, 'Traduzione', 'A1', 'Questions and Origins', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q205', 'Complete: ''_____ time does the movie start?''', '["What","Which","When","How"]', NULL, 0, 'Asking for a specific time uses ''What time''.', NULL, 'Grammatica', 'A1', 'Questions and Origins', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q206', 'Translate ''Quanto costa questo libro?''', '["How much does this book cost?","How many does this book cost?","How price is this book?","What cost this book?"]', NULL, 0, 'Asking for price uses ''How much''.', NULL, 'Traduzione', 'A1', 'Questions and Origins', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q207', 'Complete: ''_____ languages do you speak?''', '["How many","How much","How often","How long"]', NULL, 0, '''Languages'' is a plural countable noun, so we ask about the number with ''How many''; ''How much'' is for uncountable nouns, ''How often'' asks about frequency and ''How long'' about duration.', NULL, 'Grammatica', 'A1', 'Questions and Origins', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q208', 'Complete: ''_____ a big tree in the garden.''', '["There is","There are","It is","They are"]', NULL, 0, 'Singular noun ''tree'' requires ''There is''.', NULL, 'Grammatica', 'A1', 'There is / There are', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q209', 'Translate ''Ci sono tre sedie nella stanza.''', '["There are three chairs in the room.","They are three chairs in the room.","There is three chairs in the room.","Have three chairs in the room."]', NULL, 0, 'Plural noun ''chairs'' requires ''There are''.', NULL, 'Traduzione', 'A1', 'There is / There are', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q210', 'Complete: ''_____ any messages for me?''', '["Are there","Is there","Do there","Have there"]', NULL, 0, 'Question form for plural ''messages'' is ''Are there''.', NULL, 'Grammatica', 'A1', 'There is / There are', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q211', 'Translate ''C''è un buon ristorante qui vicino?''', '["Is there a good restaurant near here?","Are there a good restaurant near here?","There is a good restaurant near here?","Does there a good restaurant near here?"]', NULL, 0, 'Question form for singular noun.', NULL, 'Traduzione', 'A1', 'There is / There are', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q212', 'Complete: ''There _____ a lot of people at the party.''', '["were","was","are been","is"]', NULL, 0, '''People'' is plural, so ''were'' for past.', NULL, 'Grammatica', 'A2', 'There is / There are', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q213', 'Translate ''Non c''era nessuno in casa.''', '["There was nobody at home.","There wasn''t nobody at home.","There were nobody at home.","It was nobody at home."]', NULL, 0, 'Past singular existence with negative pronoun.', NULL, 'Traduzione', 'A2', 'There is / There are', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q214', 'Complete: ''_____ going to be a storm tomorrow.''', '["There is","It is","There are","They are"]', NULL, 0, 'Future existence ''There is going to be''.', NULL, 'Grammatica', 'B1', 'There is / There are', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q215', 'Translate ''Ci sono dei biscotti nella scatola?''', '["Are there any biscuits in the box?","Is there any biscuits in the box?","Are there some biscuits in the box?","Do there any biscuits in the box?"]', NULL, 0, 'Question plural existence with ''any''.', NULL, 'Traduzione', 'A1', 'There is / There are', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q216', 'Complete: ''_____ a mistake in this exercise.''', '["There is","There are","It is","This is"]', NULL, 0, 'Singular existence ''mistake''.', NULL, 'Grammatica', 'A1', 'There is / There are', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q217', 'Complete: ''This is not my pen. It is _____.''', '["yours","your","you","yours''"]', NULL, 0, 'Pronoun ''yours'' replaces ''your pen''.', NULL, 'Grammatica', 'A1', 'Possessives', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q218', 'Complete: ''_____ car is parked outside.''', '["Her","Hers","She","Hers''"]', NULL, 0, 'Adjective ''Her'' describes the car.', NULL, 'Grammatica', 'A1', 'Possessives', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q219', 'Complete: ''That house is _____.'' (of us)', '["ours","our","we","us"]', NULL, 0, 'Pronoun ''ours'' replaces ''our house''.', NULL, 'Grammatica', 'A1', 'Possessives', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q220', 'Complete: ''Is this book _____?'' (of him)', '["his","him","he","his''"]', NULL, 0, 'Pronoun ''his'' indicates possession by a male.', NULL, 'Grammatica', 'A1', 'Possessives', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q221', 'Complete: ''These are _____ shoes.''', '["my","mine","me","I"]', NULL, 0, 'Adjective ''my'' modifies shoes.', NULL, 'Grammatica', 'A1', 'Possessives', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q222', 'Complete: ''The dog is wagging _____ tail.''', '["its","it''s","it","its''"]', NULL, 0, '''Its'' is the possessive adjective for animals/things without an apostrophe.', NULL, 'Grammatica', 'A1', 'Possessives', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q223', 'Complete: ''Are those keys _____?'' (of them)', '["theirs","their","them","they"]', NULL, 0, 'Pronoun ''theirs'' replaces ''their keys''.', NULL, 'Grammatica', 'A1', 'Possessives', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q224', 'Complete: ''I lost _____ keys yesterday.''', '["my","mine","me","I"]', NULL, 0, 'Possessive adjective ''my'' comes before the noun.', NULL, 'Grammatica', 'A1', 'Possessives', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q225', 'Complete: ''This laptop is _____, not yours.''', '["mine","my","me","I"]', NULL, 0, 'Pronoun ''mine'' replaces ''my laptop''.', NULL, 'Grammatica', 'A1', 'Possessives', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q226', 'Translate ''Questo libro è mio.''', '["This book is mine.","This book is my.","This book is me.","This book is I."]', NULL, 0, '''Mio'' at the end of the sentence is the pronoun ''mine''.', NULL, 'Traduzione', 'A1', 'Possessives', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q227', 'Translate ''La loro casa è molto grande.''', '["Their house is very big.","Theirs house is very big.","They house is very big.","Them house is very big."]', NULL, 0, '''Loro'' as an adjective before a noun is ''their''.', NULL, 'Traduzione', 'A1', 'Possessives', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q228', 'Translate ''Quella è la tua giacca, non la sua (di lei).''', '["That is your jacket, not hers.","That is your jacket, not her.","That is yours jacket, not hers.","That is your jacket, not she."]', NULL, 0, '''La sua'' without the noun is the pronoun ''hers''.', NULL, 'Traduzione', 'A1', 'Possessives', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q229', 'Translate ''I nostri amici stanno arrivando.''', '["Our friends are coming.","Ours friends are coming.","We friends are coming.","Us friends are coming."]', NULL, 0, '''Nostri'' before the noun is ''our''.', NULL, 'Traduzione', 'A1', 'Possessives', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q230', 'Translate ''Questi soldi sono vostri?''', '["Is this money yours?","Is this money your?","Are these money yours?","Is this money you?"]', NULL, 0, 'Money is uncountable singular, ''vostri'' as a pronoun is ''yours''.', NULL, 'Traduzione', 'A1', 'Possessives', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q231', 'Translate ''Il suo (di lui) telefono è nuovo.''', '["His phone is new.","Him phone is new.","He phone is new.","His'' phone is new."]', NULL, 0, '''Suo'' for a male is ''his''.', NULL, 'Traduzione', 'A1', 'Possessives', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q232', 'Translate ''La mia macchina è rossa, la sua (di lui) è blu.''', '["My car is red, his is blue.","My car is red, him is blue.","Mine car is red, his is blue.","My car is red, he is blue."]', NULL, 0, '''La sua'' as a pronoun for a male is ''his''.', NULL, 'Traduzione', 'A1', 'Possessives', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q233', 'Translate ''Ho dimenticato il mio ombrello.''', '["I forgot my umbrella.","I forgot mine umbrella.","I forgot me umbrella.","I forgot I umbrella."]', NULL, 0, '''Il mio'' before the noun is ''my''.', NULL, 'Traduzione', 'A1', 'Possessives', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q234', 'Translate ''Quelle penne sono loro (di loro).''', '["Those pens are theirs.","Those pens are their.","Those pens are them.","Those pens are they."]', NULL, 0, '''Loro'' as a pronoun is ''theirs''.', NULL, 'Traduzione', 'A1', 'Possessives', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q235', 'Complete: ''I call _____ every day.'' (him/he/his/himself)', '["him","he","his","himself"]', NULL, 0, '''Him'' is the object pronoun for a male.', NULL, 'Grammatica', 'A1', 'Object Pronouns', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q236', 'Complete: ''She loves _____ very much.'' (me/I/my/mine)', '["me","I","my","mine"]', NULL, 0, '''Me'' is the object pronoun for first person singular.', NULL, 'Grammatica', 'A1', 'Object Pronouns', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q237', 'Complete: ''Can you help _____ with this exercise?'' (us/we/our/ours)', '["us","we","our","ours"]', NULL, 0, '''Us'' is the object pronoun for ''we''.', NULL, 'Grammatica', 'A1', 'Object Pronouns', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q238', 'Complete: ''I don''t know _____.'' (them/they/their/theirs)', '["them","they","their","theirs"]', NULL, 0, '''Them'' is the object pronoun for ''they''.', NULL, 'Grammatica', 'A1', 'Object Pronouns', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q239', 'Complete: ''Look at _____!'' (her/she/hers/herself)', '["her","she","hers","herself"]', NULL, 0, '''Her'' is the object pronoun after the preposition ''at''.', NULL, 'Grammatica', 'A1', 'Object Pronouns', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q240', 'Complete: ''He wants to speak to _____.'' (you/your/yours/yourself)', '["you","your","yours","yourself"]', NULL, 0, '''You'' is the object pronoun.', NULL, 'Grammatica', 'A1', 'Object Pronouns', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q241', 'Complete: ''Give _____ to me.'' (it/its/it''s/itself)', '["it","its","it''s","itself"]', NULL, 0, '''It'' is the object pronoun for things/animals.', NULL, 'Grammatica', 'A1', 'Object Pronouns', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q242', 'Complete: ''My parents are visiting _____.'' (me/I/my/mine)', '["me","I","my","mine"]', NULL, 0, '''Me'' receives the action of visiting.', NULL, 'Grammatica', 'A1', 'Object Pronouns', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q243', 'Complete: ''Are you listening to _____?'' (him/he/his/himself)', '["him","he","his","himself"]', NULL, 0, '''Him'' follows the preposition ''to''.', NULL, 'Grammatica', 'A1', 'Object Pronouns', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q244', 'Translate ''Non lo capisco.'' (di lui)', '["I don''t understand him.","I don''t understand he.","I don''t understand his.","I don''t understand it."]', NULL, 0, '''Lo'' referring to a man translates to ''him''.', NULL, 'Traduzione', 'A1', 'Object Pronouns', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q245', 'Translate ''Puoi vederci?''', '["Can you see us?","Can you see we?","Can you see our?","Can you see me?"]', NULL, 0, '''Ci'' translates to the object pronoun ''us''.', NULL, 'Traduzione', 'A1', 'Object Pronouns', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q246', 'Translate ''Le ho comprato un regalo.'' (a lei)', '["I bought her a present.","I bought she a present.","I bought hers a present.","I bought for her a present."]', NULL, 0, '''Le'' (to her) is translated with the object pronoun ''her''.', NULL, 'Traduzione', 'A1', 'Object Pronouns', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q247', 'Translate ''Li aspetto qui.''', '["I''ll wait for them here.","I''ll wait for they here.","I''ll wait them here.","I''m waiting they here."]', NULL, 0, '''Li'' is the object pronoun ''them'', and ''wait'' needs ''for'' before its object: ''I''ll wait for them here''. ''They'' is a subject pronoun.', NULL, 'Traduzione', 'A1', 'Object Pronouns', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q248', 'Translate ''Dammi quel libro.''', '["Give me that book.","Give I that book.","Give my that book.","Give to me that book."]', NULL, 0, '''Dammi'' uses the object pronoun ''me''.', NULL, 'Traduzione', 'A1', 'Object Pronouns', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q249', 'Translate ''Non ti credo.''', '["I don''t believe you.","I don''t believe your.","I don''t believe to you.","I not believe you."]', NULL, 0, '''Ti'' is the object pronoun ''you''.', NULL, 'Traduzione', 'A1', 'Object Pronouns', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q250', 'Translate ''Lo voglio adesso.'' (un oggetto)', '["I want it now.","I want him now.","I want that now.","I want this now."]', NULL, 0, '''Lo'' for a thing is ''it''.', NULL, 'Traduzione', 'A1', 'Object Pronouns', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q251', 'Translate ''Vieni con noi al cinema?''', '["Are you coming with us to the cinema?","Are you coming with we to the cinema?","Do you come with us to the cinema?","Are you coming to us to the cinema?"]', NULL, 0, '''Con noi'' uses the object pronoun ''us''.', NULL, 'Traduzione', 'A1', 'Object Pronouns', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q252', 'Translate ''Non li conosco.''', '["I don''t know them.","I don''t know they.","I don''t know their.","I not know them."]', NULL, 0, '''Li'' is the object pronoun ''them''.', NULL, 'Traduzione', 'A1', 'Object Pronouns', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q253', 'Complete: ''_____ is my friend, Paul.'' (near)', '["This","These","Those","That"]', NULL, 0, '''This'' is used for a singular person/thing near the speaker.', NULL, 'Grammatica', 'A1', 'Demonstratives', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q254', 'Complete: ''Look at _____ birds in the sky.''', '["those","that","this","these"]', NULL, 0, '''Those'' is used for plural things far from the speaker.', NULL, 'Grammatica', 'A1', 'Demonstratives', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q255', 'Complete: ''Are _____ your shoes here?''', '["these","this","that","those"]', NULL, 0, '''These'' is used for plural things near the speaker.', NULL, 'Grammatica', 'A1', 'Demonstratives', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q256', 'Complete: ''_____ building over there is a hospital.''', '["That","This","These","Those"]', NULL, 0, '''That'' is used for a singular thing far away.', NULL, 'Grammatica', 'A1', 'Demonstratives', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q257', 'Complete: ''_____ days are the best of my life.''', '["These","This","That","Those"]', NULL, 0, '''These'' refers to plural days in the current time.', NULL, 'Grammatica', 'A1', 'Demonstratives', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q258', 'Complete: ''I don''t like _____ kind of music.'' (near/current)', '["this","these","those","them"]', NULL, 0, '''This kind'' is singular.', NULL, 'Grammatica', 'A1', 'Demonstratives', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q259', 'Complete: ''Did you buy _____ apples from the market?'' (far/past)', '["those","that","this","them"]', NULL, 0, '''Those apples'' refers to plural items away or in the past.', NULL, 'Grammatica', 'A1', 'Demonstratives', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q260', 'Complete: ''_____ is a very interesting book.'' (holding it)', '["This","These","Those","Them"]', NULL, 0, '''This'' refers to a singular item being held.', NULL, 'Grammatica', 'A1', 'Demonstratives', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q261', 'Complete: ''Can you pass me _____ pen?'' (far)', '["that","those","these","this"]', NULL, 0, '''That'' refers to a singular item out of reach.', NULL, 'Grammatica', 'A1', 'Demonstratives', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q262', 'Translate ''Questo è il mio gatto.''', '["This is my cat.","That is my cat.","These is my cat.","Those is my cat."]', NULL, 0, '''Questo'' for one thing near the speaker is ''This''; ''that'' is for something far away, and ''these/those'' are plural.', NULL, 'Traduzione', 'A1', 'Demonstratives', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q263', 'Translate ''Quelli sono i miei libri.''', '["Those are my books.","That are my books.","These are my books.","This are my books."]', NULL, 0, '''Quelli'' (far plural) is ''Those''.', NULL, 'Traduzione', 'A1', 'Demonstratives', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q264', 'Translate ''Questa pizza è buonissima.''', '["This pizza is very good.","That pizza is very good.","These pizza is very good.","It pizza is very good."]', NULL, 0, '''Questa'' (singular, near the speaker) is ''This'': ''This pizza''; ''that'' is for something far away and ''these'' is plural.', NULL, 'Traduzione', 'A1', 'Demonstratives', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q265', 'Translate ''Queste ragazze sono italiane.''', '["These girls are Italian.","This girls are Italian.","Those girls are Italian.","That girls are Italian."]', NULL, 0, '''Queste'' (near plural) is ''These''.', NULL, 'Traduzione', 'A1', 'Demonstratives', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q266', 'Translate ''Quell''uomo è mio padre.''', '["That man is my father.","This man is my father.","Those man is my father.","The man is my father."]', NULL, 0, '''Quell'''' (far singular) is ''That''.', NULL, 'Traduzione', 'A1', 'Demonstratives', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q267', 'Translate ''Cosa sono quelle cose?''', '["What are those things?","What are these things?","What is that things?","What are that things?"]', NULL, 0, '''Quelle'' (far plural) is ''those''.', NULL, 'Traduzione', 'A1', 'Demonstratives', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q268', 'Translate ''Preferisco questo vestito.''', '["I prefer this dress.","I prefer that dress.","I prefer these dress.","I prefer those dress."]', NULL, 0, '''Questo'' (singular, near the speaker) is ''this'': ''this dress''; ''these'' and ''those'' are plural, and ''that'' refers to something far away.', NULL, 'Traduzione', 'A1', 'Demonstratives', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q269', 'Translate ''Conosci quelle persone?''', '["Do you know those people?","Do you know these people?","Do you know that people?","Do you know this people?"]', NULL, 0, '''Quelle'' (far plural) is ''those''.', NULL, 'Traduzione', 'A1', 'Demonstratives', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q270', 'Translate ''Questi sono i miei appunti.''', '["These are my notes.","This are my notes.","Those are my notes.","That are my notes."]', NULL, 0, '''Questi'' (near plural) is ''These''.', NULL, 'Traduzione', 'A1', 'Demonstratives', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q271', 'Complete: ''The cat is hiding _____ the bed.''', '["under","between","on","at"]', NULL, 0, '''Under'' means below or beneath something (''under the bed''); ''between'' needs two things, and ''on''/''at'' don''t describe a place beneath.', NULL, 'Grammatica', 'A1', 'Prepositions of Place', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q272', 'Complete: ''She is waiting _____ the bus stop.''', '["at","in","on","under"]', NULL, 0, 'Use ''at'' for a specific point or location.', NULL, 'Grammatica', 'A1', 'Prepositions of Place', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q273', 'Complete: ''The picture is hanging _____ the wall.''', '["on","in","at","under"]', NULL, 0, 'Use ''on'' for surfaces.', NULL, 'Grammatica', 'A1', 'Prepositions of Place', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q274', 'Complete: ''He lives _____ London.''', '["in","at","on","by"]', NULL, 0, 'Use ''in'' for cities, countries, and enclosed spaces.', NULL, 'Grammatica', 'A1', 'Prepositions of Place', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q275', 'Complete: ''The car is parked _____ the house.''', '["behind","under","in","on"]', NULL, 0, '''Behind'' means at the back of.', NULL, 'Grammatica', 'A1', 'Prepositions of Place', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q276', 'Complete: ''She sat _____ her two best friends.''', '["between","among","under","in"]', NULL, 0, '''Between'' is used for a position separating two things or people; ''among'' is used for more than two.', NULL, 'Grammatica', 'A1', 'Prepositions of Place', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q277', 'Complete: ''The bank is _____ the post office.''', '["next to","in","on","at"]', NULL, 0, '''Next to'' means beside.', NULL, 'Grammatica', 'A1', 'Prepositions of Place', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q278', 'Complete: ''There is a bridge _____ the river.''', '["over","under","in","at"]', NULL, 0, '''Over'' means above or across something: a bridge goes over (across) the river. ''Under'' is below, and ''in''/''at'' don''t describe this position.', NULL, 'Grammatica', 'A1', 'Prepositions of Place', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q279', 'Complete: ''I left my keys _____ the table.''', '["on","in","at","between"]', NULL, 0, '''On'' is used for surfaces.', NULL, 'Grammatica', 'A1', 'Prepositions of Place', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q280', 'Translate ''Il cane è sotto il tavolo.''', '["The dog is under the table.","The dog is on the table.","The dog is at the table.","The dog is in the table."]', NULL, 0, '''Sotto'' translates to ''under''.', NULL, 'Traduzione', 'A1', 'Prepositions of Place', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q281', 'Translate ''Sono al cinema.''', '["I am at the cinema.","I am into the cinema.","I am on the cinema.","I am to the cinema."]', NULL, 0, '''At'' is used for a place where an activity happens (at the cinema, at school); ''into'' shows movement, ''on'' is for surfaces and ''to'' for direction.', NULL, 'Traduzione', 'A1', 'Prepositions of Place', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q282', 'Translate ''C''è un ragno sul soffitto.''', '["There is a spider on the ceiling.","There is a spider at the ceiling.","There is a spider in the ceiling.","There is a spider under the ceiling."]', NULL, 0, '''Sul'' for a surface like a ceiling is ''on''.', NULL, 'Traduzione', 'A1', 'Prepositions of Place', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q283', 'Translate ''L''ufficio è vicino alla banca.''', '["The office is near the bank.","The office is in the bank.","The office is between the bank.","The office is at the bank."]', NULL, 0, '''Vicino a'' is ''near'' (''next to'' means ''accanto a''); ''between'' needs two places, and ''in''/''at'' mean the office is inside or at the bank.', NULL, 'Traduzione', 'A1', 'Prepositions of Place', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q284', 'Translate ''Il bambino è tra i suoi genitori.''', '["The child is between his parents.","The child is among his parents.","The child is next to his parents.","The child is in his parents."]', NULL, 0, '''Tra'' two people is ''between''; ''among'' is used for more than two people or things.', NULL, 'Traduzione', 'A1', 'Prepositions of Place', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q285', 'Translate ''Nasconditi dietro la porta.''', '["Hide behind the door.","Hide under the door.","Hide next to the door.","Hide in the door."]', NULL, 0, '''Dietro'' is ''behind''.', NULL, 'Traduzione', 'A1', 'Prepositions of Place', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q286', 'Translate ''Metti i vestiti nell''armadio.''', '["Put the clothes in the wardrobe.","Put the clothes on the wardrobe.","Put the clothes at the wardrobe.","Put the clothes to the wardrobe."]', NULL, 0, '''Nel'' meaning inside an enclosed space is ''in''; ''on'' is for surfaces, ''at'' for a point and ''to'' for direction, not position.', NULL, 'Traduzione', 'A1', 'Prepositions of Place', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q287', 'Translate ''Ho incontrato Marco alla stazione.''', '["I met Marco at the station.","I met Marco into the station.","I met Marco on the station.","I met Marco to the station."]', NULL, 0, '''Alla'' for a specific point or place is ''at'' (''at the station''); ''into'' shows movement inside, and ''on''/''to'' are not used here.', NULL, 'Traduzione', 'A1', 'Prepositions of Place', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q288', 'Translate ''C''è un giardino dietro la casa.''', '["There is a garden behind the house.","There is a garden under the house.","There is a garden in the house.","There is a garden next to the house."]', NULL, 0, '''Dietro'' is ''behind''.', NULL, 'Traduzione', 'A1', 'Prepositions of Place', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q289', 'Complete: ''_____ to me carefully.''', '["Listen","Listening","Listens","To listen"]', NULL, 0, 'Imperative uses the base form of the verb.', NULL, 'Grammatica', 'A1', 'Imperative', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q290', 'Complete: ''_____ open the window. It''s cold.''', '["Don''t","Not","No","Doesn''t"]', NULL, 0, 'Negative imperative uses ''Don''t''.', NULL, 'Grammatica', 'A1', 'Imperative', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q291', 'Complete: ''_____ your vegetables!''', '["Eat","Eating","Eats","To eat"]', NULL, 0, 'Use base verb for direct commands.', NULL, 'Grammatica', 'A1', 'Imperative', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q292', 'Complete: ''_____ be late for the meeting.''', '["Don''t","Not","Doesn''t","No"]', NULL, 0, 'Negative commands usually start with ''Don''t'' + base verb (''Don''t be late''); ''Not'', ''No'' and ''Doesn''t'' cannot form an imperative.', NULL, 'Grammatica', 'A1', 'Imperative', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q293', 'Complete: ''_____ quiet, please.''', '["Be","Are","Is","Am"]', NULL, 0, 'Base form of ''to be'' is used for commands.', NULL, 'Grammatica', 'A1', 'Imperative', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q294', 'Complete: ''_____ touch that plate, it''s hot.''', '["Don''t","No","Not","Doesn''t"]', NULL, 0, 'Negative commands use ''Don''t'' + base verb (''Don''t touch''); ''No'', ''Not'' and ''Doesn''t'' cannot form an imperative.', NULL, 'Grammatica', 'A1', 'Imperative', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q295', 'Complete: ''_____ your homework before dinner.''', '["Do","Does","Doing","Did"]', NULL, 0, 'The imperative uses the base form of the verb (''Do your homework''), with no -s, -ing or past form.', NULL, 'Grammatica', 'A1', 'Imperative', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q296', 'Complete: ''_____ me the salt, please.''', '["Pass","Passing","Passes","To pass"]', NULL, 0, 'The imperative uses the base form of the verb with no subject: ''Pass me the salt, please.''', NULL, 'Grammatica', 'A1', 'Imperative', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q297', 'Complete: ''_____ worry about it.''', '["Don''t","Not","No","Doesn''t"]', NULL, 0, 'Negative imperatives are formed with ''Don''t'' + base verb: ''Don''t worry about it.''', NULL, 'Grammatica', 'A1', 'Imperative', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q298', 'Translate ''Non toccare il mio telefono.''', '["Don''t touch my phone.","Not touch my phone.","No touch my phone.","Doesn''t touch my phone."]', NULL, 0, 'Negative imperative is formed with ''Don''t''.', NULL, 'Traduzione', 'A1', 'Imperative', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q299', 'Translate ''Fai attenzione!''', '["Pay attention!","Do attention!","Make attention!","Attention you!"]', NULL, 0, '''Fare attenzione'' is ''pay attention''.', NULL, 'Traduzione', 'A1', 'Imperative', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q300', 'Translate ''Ascoltami quando parlo.''', '["Listen to me when I speak.","Listen me when I speak.","Hear me when I speak.","Hear to me when I speak."]', NULL, 0, 'The English verb ''listen'' needs ''to'' before its object (''listen to me''); ''hear'' means ''sentire'' and never takes ''to''.', NULL, 'Traduzione', 'A1', 'Imperative', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q301', 'Translate ''Non dimenticare le chiavi.''', '["Don''t forget your keys.","Not forget your keys.","No forget your keys.","Don''t missing your keys."]', NULL, 0, 'Negative command with ''Don''t''.', NULL, 'Traduzione', 'A1', 'Imperative', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q302', 'Translate ''Chiudi la porta, per favore.''', '["Close the door, please.","Closing the door, please.","To close the door, please.","You close the door, please."]', NULL, 0, 'Base verb for command.', NULL, 'Traduzione', 'A1', 'Imperative', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q303', 'Translate ''Non parlare durante l''esame.''', '["Don''t speak during the exam.","Not speak during the exam.","Doesn''t speak during the exam.","Don''t speaking during the exam."]', NULL, 0, 'Negative imperatives use ''Don''t'' + base verb (''Don''t speak''), not ''Not'', ''Doesn''t'' or ''Don''t'' + -ing.', NULL, 'Traduzione', 'A1', 'Imperative', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q304', 'Translate ''Aspetta qui un momento.''', '["Wait here a moment.","Waiting here a moment.","Wait here a time.","Stay here a moment."]', NULL, 0, 'The imperative is the base form of the verb (''Wait here''); ''aspettare'' is ''wait'' (not ''stay''), and ''un momento'' is ''a moment'', not ''a time''.', NULL, 'Traduzione', 'A1', 'Imperative', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q305', 'Translate ''Scrivete i vostri nomi sul foglio.''', '["Write your names on the paper.","Writing your names on the paper.","You write your names on the paper.","To write your names on the paper."]', NULL, 0, 'Imperative is the same for singular and plural ''you''.', NULL, 'Traduzione', 'A1', 'Imperative', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q306', 'Translate ''Non fumare in questa stanza.''', '["Don''t smoke in this room.","Smoke not in this room.","Not smoke in this room.","Doesn''t smoke in this room."]', NULL, 0, '''Don''t'' + base verb forms the negative imperative (''Don''t smoke''); ''Not smoke'', ''Smoke not'' and ''Doesn''t smoke'' are not correct imperative forms.', NULL, 'Traduzione', 'A1', 'Imperative', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q307', 'Complete: ''I _____ to visit my grandparents this weekend.''', '["am going","go","going","will going"]', NULL, 0, 'We use ''am going to'' for planned future intentions.', NULL, 'Grammatica', 'A2', 'Future: going to', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q308', 'Complete: ''Look at those dark clouds. It _____ rain.''', '["is going to","will","going to","rains"]', NULL, 0, '''Going to'' is used when there is present evidence for a future event.', NULL, 'Grammatica', 'A2', 'Future: going to', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q309', 'Complete: ''What _____ you going to do tonight?''', '["are","do","is","will"]', NULL, 0, 'Question form requires the verb ''to be'' (are) before the subject.', NULL, 'Grammatica', 'A2', 'Future: going to', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q310', 'Complete: ''She _____ not going to buy a new car.''', '["is","does","has","will"]', NULL, 0, 'Negative form uses ''to be'' + not + going to.', NULL, 'Grammatica', 'A2', 'Future: going to', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q311', 'Complete: ''We are going to _____ a movie after dinner.''', '["watch","watching","watched","watches"]', NULL, 0, '''Going to'' is followed by the base form of the verb.', NULL, 'Grammatica', 'A2', 'Future: going to', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q312', 'Complete: ''_____ he going to invite her to the party?''', '["Is","Does","Will","Has"]', NULL, 0, 'Question form for third person singular uses ''Is''.', NULL, 'Grammatica', 'A2', 'Future: going to', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q313', 'Complete: ''They _____ going to start a new business next year.''', '["are","will","do","have"]', NULL, 0, 'Plural subject takes ''are''.', NULL, 'Grammatica', 'A2', 'Future: going to', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q314', 'Complete: ''I''m going to _____ English in London.''', '["study","studying","studied","studies"]', NULL, 0, 'Base verb ''study'' after ''going to''.', NULL, 'Grammatica', 'A2', 'Future: going to', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q315', 'Complete: ''My parents are _____ to travel to Spain.''', '["going","go","will","goes"]', NULL, 0, 'Part of the structure ''are going to''.', NULL, 'Grammatica', 'A2', 'Future: going to', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q316', 'Translate ''Cosa hai intenzione di fare?''', '["What are you going to do?","What will you do?","What do you do?","What you are going to do?"]', NULL, 0, '''Avere intenzione di'' (a plan or intention) is expressed with ''be going to'' + base verb: ''What are you going to do?''. In questions the verb ''be'' comes before the subject (''are you'', not ''you are'').', NULL, 'Traduzione', 'A2', 'Future: going to', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q317', 'Translate ''Non ho intenzione di aspettare tutto il giorno.''', '["I am not going to wait all day.","I don''t go to wait all day.","I won''t to wait all day.","I am not going to waiting all day."]', NULL, 0, 'Negative ''going to''.', NULL, 'Traduzione', 'A2', 'Future: going to', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q318', 'Translate ''Lui studierà medicina all''università.'' (intenzione)', '["He is going to study medicine at university.","He will study medicine at university.","He is studying medicine at university.","He studies medicine at university."]', NULL, 0, 'Intentions use ''going to''.', NULL, 'Traduzione', 'A2', 'Future: going to', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q319', 'Translate ''Abbiamo intenzione di comprare una nuova casa.''', '["We are going to buy a new house.","We will buy a new house.","We are going buy a new house.","We buy a new house."]', NULL, 0, 'An intention or a decision already made uses ''be going to'' + base verb (''We are going to buy''); ''to'' cannot be left out.', NULL, 'Traduzione', 'A2', 'Future: going to', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q320', 'Translate ''Pioverà a breve.'' (guardando il cielo scuro)', '["It is going to rain soon.","It will rain soon.","It is raining soon.","It rains soon."]', NULL, 0, 'Prediction based on evidence uses ''going to''.', NULL, 'Traduzione', 'A2', 'Future: going to', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q321', 'Translate ''Non parteciperanno all''incontro.'' (intenzione)', '["They aren''t going to attend the meeting.","They won''t attend the meeting.","They don''t attend the meeting.","They aren''t attending the meeting."]', NULL, 0, 'A negative intention uses ''be not going to'' + base verb: ''They aren''t going to attend the meeting.''', NULL, 'Traduzione', 'A2', 'Future: going to', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q322', 'Translate ''Cosa mangerai a cena?'' (che programmi hai)', '["What are you going to eat for dinner?","What will you eat for dinner?","What do you eat for dinner?","What you going to eat for dinner?"]', NULL, 0, 'To ask about plans already made, we use ''be going to'' in the question form: ''What are you going to eat?''', NULL, 'Traduzione', 'A2', 'Future: going to', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q323', 'Translate ''Venderà la sua macchina?'' (ha intenzione di)', '["Is she going to sell her car?","Will she sell her car?","Does she sell her car?","Is she sell her car?"]', NULL, 0, 'Question about intention.', NULL, 'Traduzione', 'A2', 'Future: going to', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q324', 'Translate ''Cadrà!'' (lo vedi correre sul ghiaccio)', '["He''s going to fall!","He is going fall!","He falls!","He falling!"]', NULL, 0, 'When we predict something from evidence we can see now (he''s running on the ice), we use ''be going to'' + base verb: ''He''s going to fall!''', NULL, 'Traduzione', 'A2', 'Future: going to', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q325', 'Complete: ''I _____ TV when the phone rang.''', '["was watching","watched","am watching","were watching"]', NULL, 0, 'Past continuous for a long action interrupted by a short one.', NULL, 'Grammatica', 'A2', 'Past Continuous', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q326', 'Complete: ''While she was reading, her brother _____ video games.''', '["was playing","played","playing","is playing"]', NULL, 0, 'Two long actions happening at the same time in the past.', NULL, 'Grammatica', 'A2', 'Past Continuous', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q327', 'Complete: ''What _____ you doing at 8 PM yesterday?''', '["were","was","are","did"]', NULL, 0, '''You'' takes the auxiliary ''were'' in the past continuous.', NULL, 'Grammatica', 'A2', 'Past Continuous', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q328', 'Complete: ''They _____ in the park when it started to rain.''', '["were walking","was walking","are walking","walking"]', NULL, 0, 'The Past Continuous (''were walking'', plural subject) describes the longer background action interrupted by a shorter Past Simple action (''it started to rain'').', NULL, 'Grammatica', 'A2', 'Past Continuous', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q329', 'Complete: ''He _____ (not) listening to the teacher.''', '["wasn''t","weren''t","didn''t","isn''t"]', NULL, 0, '''He'' takes ''wasn''t'' in negative past continuous.', NULL, 'Grammatica', 'A2', 'Past Continuous', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q330', 'Complete: ''While I _____ home, I saw a car accident.''', '["was driving","drove","am driving","was drive"]', NULL, 0, 'Continuous action in the past (''while'' often signals continuous).', NULL, 'Grammatica', 'A2', 'Past Continuous', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q331', 'Complete: ''We were having dinner when the lights _____ out.''', '["went","were going","go","gone"]', NULL, 0, 'The interrupting action is in the past simple (''went'').', NULL, 'Grammatica', 'A2', 'Past Continuous', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q332', 'Complete: ''_____ it raining when you left?''', '["Was","Were","Did","Is"]', NULL, 0, 'In the Past Continuous, the singular subject ''it'' takes ''was'': ''Was it raining when you left?''', NULL, 'Grammatica', 'A2', 'Past Continuous', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q333', 'Complete: ''I broke my leg while I _____ football.''', '["was playing","played","am playing","play"]', NULL, 0, 'Long background action in past continuous.', NULL, 'Grammatica', 'A2', 'Past Continuous', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q334', 'Translate ''Cosa stavi facendo quando ti ho chiamato?''', '["What were you doing when I called you?","What did you do when I called you?","What was you doing when I called you?","What are you doing when I called you?"]', NULL, 0, 'Question in past continuous, interrupting action in past simple.', NULL, 'Traduzione', 'A2', 'Past Continuous', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q335', 'Translate ''Stavo dormendo quando l''allarme ha suonato.''', '["I was sleeping when the alarm rang.","I slept when the alarm was ringing.","I was sleeping when the alarm was ringing.","I slept when the alarm rang."]', NULL, 0, 'Background action (sleeping), interruption (rang).', NULL, 'Traduzione', 'A2', 'Past Continuous', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q336', 'Translate ''Mentre camminavamo, abbiamo trovato dei soldi.''', '["While we were walking, we found some money.","While we walked, we were finding some money.","When we were walking, we were finding some money.","While we walking, we found some money."]', NULL, 0, '''While'' + past continuous, then past simple.', NULL, 'Traduzione', 'A2', 'Past Continuous', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q337', 'Translate ''Lei non stava guardando la TV, stava leggendo.''', '["She wasn''t watching TV, she was reading.","She didn''t watch TV, she was reading.","She wasn''t watching TV, she read.","She wasn''t watch TV, she was reading."]', NULL, 0, 'Both actions are past continuous.', NULL, 'Traduzione', 'A2', 'Past Continuous', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q338', 'Translate ''Mentre cucinavo, lui ascoltava la musica.''', '["While I was cooking, he was listening to music.","While I was cook, he was listening to music.","While I cooking, he was listening to music.","While I was cooking, he were listening to music."]', NULL, 0, 'Two long actions in progress at the same time in the past both take the Past Continuous (was/were + -ing); with ''he'' we use ''was'', not ''were''.', NULL, 'Traduzione', 'A2', 'Past Continuous', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q339', 'Translate ''Pioveva forte ieri mattina?''', '["Was it raining hard yesterday morning?","Did it raining hard yesterday morning?","Were it raining hard yesterday morning?","Is it raining hard yesterday morning?"]', NULL, 0, '''Pioveva'' describes an action in progress at a past time, so we use the Past Continuous question ''Was it raining...?''; ''it'' takes ''was'', and ''did'' is never followed by -ing.', NULL, 'Traduzione', 'A2', 'Past Continuous', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q340', 'Translate ''Non stavamo andando troppo veloci.''', '["We weren''t going too fast.","We didn''t go too fast.","We wasn''t going too fast.","We aren''t going too fast."]', NULL, 0, 'Negative past continuous with ''were''.', NULL, 'Traduzione', 'A2', 'Past Continuous', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q341', 'Translate ''Cosa pensavi in quel momento?''', '["What were you thinking at that moment?","What did you think at that moment?","What was you thinking at that moment?","What are you thinking at that moment?"]', NULL, 0, 'Asking about ongoing thoughts at a past moment.', NULL, 'Traduzione', 'A2', 'Past Continuous', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q342', 'Translate ''Loro ridevano quando sono entrato.''', '["They were laughing when I entered.","They laughed when I was entering.","They were laughing when I was entering.","They laughed when I entered."]', NULL, 0, 'Background action (laughing), short interruption (entered).', NULL, 'Traduzione', 'A2', 'Past Continuous', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q343', 'Complete: ''You look tired. You _____ go to bed early.''', '["should","have to","mustn''t","don''t have to"]', NULL, 0, '''Should'' is used for advice.', NULL, 'Grammatica', 'A2', 'Modals of Obligation and Advice', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q344', 'Complete: ''In many countries, you _____ wear a seatbelt when driving.''', '["have to","should","don''t have to","mustn''t"]', NULL, 0, '''Have to'' is used for a strong obligation or law.', NULL, 'Grammatica', 'A2', 'Modals of Obligation and Advice', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q345', 'Complete: ''Tomorrow is Sunday, so I _____ wake up early.''', '["don''t have to","mustn''t","shouldn''t","haven''t to"]', NULL, 0, '''Don''t have to'' means it''s not necessary (lack of obligation).', NULL, 'Grammatica', 'A2', 'Modals of Obligation and Advice', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q346', 'Complete: ''You _____ use your phone during the exam! It''s forbidden.''', '["mustn''t","don''t have to","shouldn''t","haven''t to"]', NULL, 0, '''Mustn''t'' means it is strictly prohibited.', NULL, 'Grammatica', 'A2', 'Modals of Obligation and Advice', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q347', 'Complete: ''_____ I wear a suit to the interview?''', '["Should","Does","Have to","Do I must"]', NULL, 0, '''Should'' is used to ask for an opinion or advice (''Should I...?''); ''have to'' needs ''do'' in questions (''Do I have to...?''), and modals like ''must'' never combine with ''do''.', NULL, 'Grammatica', 'A2', 'Modals of Obligation and Advice', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q348', 'Complete: ''We have plenty of time. We _____ hurry.''', '["don''t have to","mustn''t","shouldn''t","don''t must"]', NULL, 0, 'No obligation to hurry.', NULL, 'Grammatica', 'A2', 'Modals of Obligation and Advice', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q349', 'Complete: ''All visitors _____ wear a helmet on the building site. It''s the law.''', '["must","mustn''t","don''t have to","musts"]', NULL, 0, '''Must'' + base verb expresses a strong obligation or a rule (''It''s the law''); ''mustn''t'' means it is forbidden, ''don''t have to'' that it isn''t necessary, and ''must'' never takes -s.', NULL, 'Grammatica', 'A2', 'Modals of Obligation and Advice', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q350', 'Complete: ''He _____ wear glasses to read because his eyesight is bad.''', '["has to","must to","musts","have to"]', NULL, 0, '''Has to'' expresses a necessity (his eyesight is bad, so he needs glasses); with ''he'' we use ''has to'', not ''have to'', and ''must'' never takes -s or ''to''.', NULL, 'Grammatica', 'A2', 'Modals of Obligation and Advice', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q351', 'Complete: ''Do I _____ pay for this ticket now?''', '["have to","must","should","had to"]', NULL, 0, 'Question form for obligation is ''Do/Does ... have to''.', NULL, 'Grammatica', 'A2', 'Modals of Obligation and Advice', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q352', 'Translate ''Dovresti mangiare più verdure.''', '["You should eat more vegetables.","You must eat more vegetables.","You have to eat more vegetables.","You shouldn''t eat more vegetables."]', NULL, 0, '''Should'' + base verb gives advice (''Dovresti'' = ''You should''); ''must'' and ''have to'' express obligation, not advice.', NULL, 'Traduzione', 'A2', 'Modals of Obligation and Advice', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q353', 'Translate ''Non devi per forza venire se sei stanco.''', '["You don''t have to come if you''re tired.","You mustn''t come if you''re tired.","You shouldn''t come if you''re tired.","You haven''t to come if you''re tired."]', NULL, 0, '''Don''t have to'' means it isn''t necessary (lack of obligation); ''mustn''t'' would mean it is forbidden.', NULL, 'Traduzione', 'A2', 'Modals of Obligation and Advice', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q354', 'Translate ''Non devi assolutamente toccare quel filo!''', '["You mustn''t touch that wire!","You don''t have to touch that wire!","You shouldn''t touch that wire!","You haven''t to touch that wire!"]', NULL, 0, '''Mustn''t'' expresses a strong prohibition (''Non devi assolutamente''); ''don''t have to'' only means it isn''t necessary.', NULL, 'Traduzione', 'A2', 'Modals of Obligation and Advice', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q355', 'Translate ''Lui deve lavorare fino a tardi oggi.'' (obbligo esterno)', '["He has to work late today.","He should work late today.","He have to work late today.","He musts work late today."]', NULL, 0, 'External obligation with ''has to''.', NULL, 'Traduzione', 'A2', 'Modals of Obligation and Advice', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q356', 'Translate ''Non dovresti bere così tanto caffè.''', '["You shouldn''t drink so much coffee.","You mustn''t drink so much coffee.","You don''t have to drink so much coffee.","You haven''t to drink so much coffee."]', NULL, 0, '''Shouldn''t'' + base verb gives negative advice (''Non dovresti''); ''mustn''t'' would be a prohibition, not advice.', NULL, 'Traduzione', 'A2', 'Modals of Obligation and Advice', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q357', 'Translate ''Devo togliermi le scarpe?''', '["Do I have to take off my shoes?","Must I to take off my shoes?","Do I must take off my shoes?","Have I to take off my shoes?"]', NULL, 0, 'Questions about rules or obligation use ''Do I have to'' + base verb; ''must'' is never followed by ''to'' or used with ''do'', and ''Have I to'' is not correct.', NULL, 'Traduzione', 'A2', 'Modals of Obligation and Advice', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q358', 'Translate ''Non hai bisogno di pagare, è gratis.''', '["You don''t have to pay, it''s free.","You mustn''t pay, it''s free.","You shouldn''t pay, it''s free.","You haven''t to pay, it''s free."]', NULL, 0, '''Don''t have to'' means there is no obligation (it''s free, so paying isn''t necessary); ''mustn''t'' would mean that paying is forbidden.', NULL, 'Traduzione', 'A2', 'Modals of Obligation and Advice', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q359', 'Translate ''Cosa dovrei fare?''', '["What should I do?","What must I do?","What have I to do?","What do I do?"]', NULL, 0, '''Should'' is used to ask for advice: ''What should I do?'' (''Cosa dovrei fare?'').', NULL, 'Traduzione', 'A2', 'Modals of Obligation and Advice', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q360', 'Translate ''Non devi dire niente a nessuno, è un segreto!''', '["You mustn''t tell anyone, it''s a secret!","You don''t have to tell anyone, it''s a secret!","You shouldn''t tell anyone, it''s a secret!","You haven''t to tell anyone, it''s a secret!"]', NULL, 0, '''Mustn''t'' expresses prohibition: telling anyone is not allowed because it''s a secret. ''Don''t have to'' would only mean it isn''t necessary.', NULL, 'Traduzione', 'A2', 'Modals of Obligation and Advice', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q361', 'Complete: ''She speaks English very _____.'' (good/well)', '["well","good","goodly","welling"]', NULL, 0, '''Well'' is the adverb form of ''good''.', NULL, 'Grammatica', 'A2', 'Adverbs of Manner', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q362', 'Complete: ''He drives very _____. It''s dangerous!''', '["fast","fastly","quick","speedy"]', NULL, 0, '''Fast'' is both an adjective and an adverb.', NULL, 'Grammatica', 'A2', 'Adverbs of Manner', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q363', 'Complete: ''Please do your work _____. Take your time.''', '["carefully","careful","careless","carelessly"]', NULL, 0, '''Carefully'' describes how to do the work.', NULL, 'Grammatica', 'A2', 'Adverbs of Manner', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q364', 'Complete: ''They won the game _____. They were much better.''', '["easily","easy","easier","easying"]', NULL, 0, '''Easily'' is the adverb form of ''easy'' (y changes to i + ly).', NULL, 'Grammatica', 'A2', 'Adverbs of Manner', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q365', 'Complete: ''The old man walked _____ down the street.''', '["slowly","slow","slower","slowingly"]', NULL, 0, '''Slowly'' describes the verb ''walked''.', NULL, 'Grammatica', 'A2', 'Adverbs of Manner', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q366', 'Complete: ''She looked at him _____ when he broke the glass.''', '["angrily","angry","angrier","angrying"]', NULL, 0, 'Adverb formed from ''angry''.', NULL, 'Grammatica', 'A2', 'Adverbs of Manner', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q367', 'Complete: ''He worked _____ to pass the exam.''', '["hard","hardly","hardy","hards"]', NULL, 0, '''Hard'' is an irregular adverb meaning ''with effort'' (the same form as the adjective). ''Hardly'' means ''almost not'', and ''hardy'' and ''hards'' are not the adverb.', NULL, 'Grammatica', 'A2', 'Adverbs of Manner', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q368', 'Complete: ''The children were playing _____ in the garden.''', '["happily","happy","happier","happiness"]', NULL, 0, '''Happily'' is the adverb of ''happy'' (y becomes i + -ly); we need an adverb to describe how they were playing.', NULL, 'Grammatica', 'A2', 'Adverbs of Manner', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q369', 'Complete: ''I can run very _____.''', '["fast","fastly","quick","faster"]', NULL, 0, '''Fast'' is an irregular adverb.', NULL, 'Grammatica', 'A2', 'Adverbs of Manner', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q370', 'Translate ''Ha risposto alla domanda velocemente.''', '["He answered the question quickly.","He answered the question quick.","He answered the question fastly.","He answered the question quicker."]', NULL, 0, '''Velocemente'' is ''quickly''.', NULL, 'Traduzione', 'A2', 'Adverbs of Manner', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q371', 'Translate ''Canta davvero bene.''', '["She sings really well.","She sings really good.","She sings really goodly.","She sings really nice."]', NULL, 0, '''Bene'' is the adverb ''well''.', NULL, 'Traduzione', 'A2', 'Adverbs of Manner', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q372', 'Translate ''Hanno lavorato duramente tutto il giorno.''', '["They worked hard all day.","They worked hardly all day.","They worked difficultly all day.","They worked heavy all day."]', NULL, 0, '''Duramente'' (con fatica) is ''hard''.', NULL, 'Traduzione', 'A2', 'Adverbs of Manner', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q373', 'Translate ''Per favore, parla lentamente.''', '["Please speak slowly.","Please speak slow.","Please speak slowlier.","Please speak slowingly."]', NULL, 0, '''Lentamente'' is the adverb ''slowly'' (adjective ''slow'' + -ly); we need an adverb to describe how someone speaks.', NULL, 'Traduzione', 'A2', 'Adverbs of Manner', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q374', 'Translate ''Ha chiuso la porta silenziosamente.''', '["He closed the door quietly.","He closed the door quiet.","He closed the door quietlyly.","He closed the door silent."]', NULL, 0, '''Silenziosamente'' is ''quietly''.', NULL, 'Traduzione', 'A2', 'Adverbs of Manner', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q375', 'Translate ''Hanno risolto il problema facilmente.''', '["They solved the problem easily.","They solved the problem easy.","They solved the problem with easy.","They solved the problem easier."]', NULL, 0, '''Facilmente'' is ''easily''.', NULL, 'Traduzione', 'A2', 'Adverbs of Manner', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q376', 'Translate ''Guida sempre con molta attenzione (attentamente).''', '["He always drives carefully.","He always drives careful.","He always drives care.","He always drives with careful."]', NULL, 0, '''Attentamente'' is ''carefully''.', NULL, 'Traduzione', 'A2', 'Adverbs of Manner', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q377', 'Translate ''L''insegnante ha spiegato la regola chiaramente.''', '["The teacher explained the rule clearly.","The teacher explained the rule clear.","The teacher explained the rule cleary.","The teacher explained the rule clearing."]', NULL, 0, '''Chiaramente'' is ''clearly''.', NULL, 'Traduzione', 'A2', 'Adverbs of Manner', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q378', 'Translate ''Ho capito perfettamente.''', '["I understood perfectly.","I understood perfect.","I understood perfection.","I understood perfectlyly."]', NULL, 0, '''Perfettamente'' is ''perfectly''.', NULL, 'Traduzione', 'A2', 'Adverbs of Manner', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q379', 'Complete the sentence: ''If I _____ the lottery, I would buy a big house.''', '["win","won","will win","had won"]', NULL, 1, 'Second Conditional uses ''If + Past Simple, would + infinitive'' for unreal present/future situations.', NULL, 'Grammatica', 'B1', 'Second Conditional', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q380', 'Translate ''Se fossi in te, studierei di più.''', '["If I am you, I will study more.","If I were you, I would study more.","If I was you, I study more.","If I would be you, I studied more."]', NULL, 1, 'In the Second Conditional, ''were'' is typically used for all subjects in the ''if'' clause (If I were you).', NULL, 'Traduzione', 'B1', 'Second Conditional', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q381', 'Complete the sentence: ''If I had studied, I _____ the exam.''', '["would pass","passed","would have passed","will pass"]', NULL, 2, 'Third Conditional uses ''If + Past Perfect, would have + past participle'' for impossible past situations.', NULL, 'Grammatica', 'B1', 'Third Conditional', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q382', 'Translate ''Se fossimo partiti prima, non avremmo perso il treno.''', '["If we left earlier, we wouldn''t miss the train.","If we had left earlier, we wouldn''t have missed the train.","If we would leave earlier, we hadn''t missed the train.","If we have left earlier, we didn''t miss the train."]', NULL, 1, 'Third conditional structure for regrets about the past.', NULL, 'Traduzione', 'B1', 'Third Conditional', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q383', 'Complete the sentence: ''The letter _____ by John yesterday.''', '["wrote","was written","is written","writes"]', NULL, 1, 'Past Simple Passive structure is ''was/were + past participle''.', NULL, 'Grammatica', 'B1', 'Passive Voice', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q384', 'Translate ''La casa viene costruita proprio ora.''', '["The house is built right now.","The house builds right now.","The house is being built right now.","The house has been built right now."]', NULL, 2, 'Present Continuous Passive requires ''is/are being + past participle''.', NULL, 'Traduzione', 'B1', 'Passive Voice', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q385', 'Change to reported speech: He said, ''I am tired.''', '["He said that he is tired.","He said that I was tired.","He said that he was tired.","He said he has been tired."]', NULL, 2, 'In reported speech, present simple changes to past simple (''am'' becomes ''was'').', NULL, 'Grammatica', 'B1', 'Reported Speech', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q386', 'Change to reported speech: ''I will call you,'' she told me.', '["She told me she will call me.","She told me she would call me.","She told me I would call her.","She told me she called me."]', NULL, 1, 'In reported speech, ''will'' changes to ''would''.', NULL, 'Grammatica', 'B1', 'Reported Speech', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q387', 'Complete the sentence: ''When I arrived at the station, the train _____.''', '["already left","has already left","had already left","already leaves"]', NULL, 2, 'The Past Perfect (''had left'') shows an action that happened before another past action (''arrived'').', NULL, 'Grammatica', 'B1', 'Past Perfect', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q388', 'Translate ''Avevo già mangiato quando mi hai chiamato.''', '["I already ate when you called me.","I had already eaten when you called me.","I have already eaten when you called me.","I was eating when you called me."]', NULL, 1, 'We use the Past Perfect (''had eaten'') for the action that happened first.', NULL, 'Traduzione', 'B1', 'Past Perfect', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q389', 'Complete the sentence: ''I _____ tennis when I was young.''', '["used to play","was playing","am used to play","use to play"]', NULL, 0, '''Used to + infinitive'' describes a past habit that is no longer true.', NULL, 'Grammatica', 'B1', 'Used to', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q390', 'Choose the correct negative form:', '["She didn''t used to like vegetables.","She hasn''t used to like vegetables.","She didn''t use to like vegetables.","She don''t use to like vegetables."]', NULL, 2, 'The negative form is ''didn''t use to'' (without the ''d'' in use).', NULL, 'Grammatica', 'B1', 'Used to', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q391', 'Complete the sentence: ''The man _____ lives next door is a doctor.''', '["which","who","whose","where"]', NULL, 1, '''Who'' is the relative pronoun used for people.', NULL, 'Grammatica', 'B1', 'Relative Clauses', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q392', 'Complete the sentence: ''That''s the house _____ I grew up.''', '["which","who","whose","where"]', NULL, 3, '''Where'' is used as a relative pronoun for places.', NULL, 'Grammatica', 'B1', 'Relative Clauses', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q393', 'Complete the sentence: ''The girl _____ car was stolen is at the police station.''', '["who","which","whose","that"]', NULL, 2, '''Whose'' indicates possession.', NULL, 'Grammatica', 'B1', 'Relative Clauses', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q394', 'Complete the sentence: ''You are Italian, _____?''', '["are you","aren''t you","don''t you","isn''t it"]', NULL, 1, 'Affirmative statements take a negative question tag (''aren''t you?'').', NULL, 'Grammatica', 'B1', 'Question Tags', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q395', 'Complete the sentence: ''She didn''t go to the party, _____?''', '["did she","didn''t she","does she","was she"]', NULL, 0, 'Negative statements take an affirmative question tag (''did she?'').', NULL, 'Grammatica', 'B1', 'Question Tags', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q396', 'Complete the sentence: ''He has a Ferrari and a mansion. He _____ be very rich.''', '["can","must","should","might"]', NULL, 1, '''Must'' is used for strong logical deductions based on evidence.', NULL, 'Grammatica', 'B1', 'Modals of Deduction', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q397', 'Complete the sentence: ''That _____ be Sarah. Sarah is currently in London.''', '["mustn''t","shouldn''t","can''t","might not"]', NULL, 2, '''Can''t'' is the negative logical deduction (you are sure something is not true).', NULL, 'Grammatica', 'B1', 'Modals of Deduction', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q398', 'Complete the sentence: ''I really enjoy _____ books in my free time.''', '["to read","read","reading","to reading"]', NULL, 2, 'The verb ''enjoy'' is followed by a gerund (-ing form).', NULL, 'Grammatica', 'B1', 'Gerunds vs Infinitives', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q399', 'Complete the sentence: ''She decided _____ a new car.''', '["buying","to buy","buy","bought"]', NULL, 1, 'The verb ''decide'' is followed by an infinitive with ''to''.', NULL, 'Grammatica', 'B1', 'Gerunds vs Infinitives', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q400', 'Complete the sentence: ''Do you mind _____ the window?''', '["open","to open","opening","opened"]', NULL, 2, 'The verb ''mind'' is followed by a gerund (-ing form).', NULL, 'Grammatica', 'B1', 'Gerunds vs Infinitives', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q401', 'The restaurant _____ we had dinner is very expensive.', '["where","which","that","who"]', NULL, 0, '''Where'' refers to a place.', NULL, 'Grammatica', 'B1', 'Relative Clauses', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q402', 'This is the man _____ dog bit me.', '["whose","who","which","that"]', NULL, 0, '''Whose'' shows possession.', NULL, 'Grammatica', 'B1', 'Relative Clauses', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q403', 'My sister, _____ lives in London, is coming to visit.', '["who","that","which","where"]', NULL, 0, 'Non-defining relative clauses for people use ''who'', not ''that''.', NULL, 'Grammatica', 'B1', 'Relative Clauses', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q404', 'Translate: ''Il film che abbiamo visto ieri era noioso.''', '["The movie which we watched yesterday was boring.","The movie who we watched yesterday was boring.","The movie where we watched yesterday was boring.","The movie whose we watched yesterday was boring."]', NULL, 0, '''Which'' or ''that'' is used for things.', NULL, 'Traduzione', 'B1', 'Relative Clauses', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q405', 'Translate: ''La donna la cui auto è stata rubata è la mia vicina.''', '["The woman whose car was stolen is my neighbor.","The woman who car was stolen is my neighbor.","The woman which car was stolen is my neighbor.","The woman that car was stolen is my neighbor."]', NULL, 0, '''Whose'' translates ''la cui / il cui''.', NULL, 'Traduzione', 'B1', 'Relative Clauses', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q406', 'The days _____ I was young were the best.', '["when","where","which","who"]', NULL, 0, '''When'' refers to a time.', NULL, 'Grammatica', 'B1', 'Relative Clauses', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q407', 'I know a place _____ you can hide.', '["where","which","that","when"]', NULL, 0, '''Where'' refers to a location.', NULL, 'Grammatica', 'B1', 'Relative Clauses', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q408', 'The student _____ got the highest grade is from Spain.', '["who","which","where","whose"]', NULL, 0, '''Who'' refers to people.', NULL, 'Grammatica', 'B1', 'Relative Clauses', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q409', 'Translate: ''Questo è il libro di cui ti parlavo.''', '["This is the book which I was telling you about.","This is the book who I was telling you about.","This is the book where I was telling you about.","This is the book whose I was telling you about."]', NULL, 0, '''Which'' is used for things.', NULL, 'Traduzione', 'B1', 'Relative Clauses', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q410', 'Translate: ''Parigi, che è la capitale della Francia, è bellissima.''', '["Paris, which is the capital of France, is beautiful.","Paris, who is the capital of France, is beautiful.","Paris, where is the capital of France, is beautiful.","Paris, that is the capital of France, is beautiful."]', NULL, 0, 'Non-defining relative clauses for things use ''which''.', NULL, 'Traduzione', 'B1', 'Relative Clauses', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q411', 'Someone _____ travels a lot is lucky.', '["who","which","whose","where"]', NULL, 0, '''Who'' refers to a person.', NULL, 'Grammatica', 'B1', 'Relative Clauses', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q412', 'The cake _____ she made was delicious.', '["which","who","whose","where"]', NULL, 0, '''Which'' refers to things.', NULL, 'Grammatica', 'B1', 'Relative Clauses', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q413', 'A library is a place _____ you can borrow books.', '["where","which","who","when"]', NULL, 0, '''Where'' is for places.', NULL, 'Grammatica', 'B1', 'Relative Clauses', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q414', 'The boy _____ sister is in my class is very tall.', '["whose","who","which","that"]', NULL, 0, '''Whose'' indicates possession (the sister of the boy).', NULL, 'Grammatica', 'B1', 'Relative Clauses', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q415', 'Winter is the season _____ it snows.', '["when","which","where","who"]', NULL, 0, '''When'' is used for periods of time.', NULL, 'Grammatica', 'B1', 'Relative Clauses', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q416', 'I always try to avoid _____ in traffic during rush hour.', '["driving","to drive","drive","drove"]', NULL, 0, '''Avoid'' is always followed by the -ing form (gerund), never by the infinitive: ''avoid driving''.', NULL, 'Grammatica', 'B1', 'Gerunds vs Infinitives', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q417', 'We hope _____ you again soon.', '["to see","seeing","see","saw"]', NULL, 0, '''Hope'' is followed by the infinitive with ''to''.', NULL, 'Grammatica', 'B1', 'Gerunds vs Infinitives', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q418', 'Avoid _____ mistakes by checking your work.', '["making","to make","make","made"]', NULL, 0, '''Avoid'' takes the gerund (-ing form).', NULL, 'Grammatica', 'B1', 'Gerunds vs Infinitives', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q419', 'She promised _____ me with my homework.', '["to help","helping","help","helped"]', NULL, 0, '''Promise'' takes the infinitive with ''to''.', NULL, 'Grammatica', 'B1', 'Gerunds vs Infinitives', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q420', 'Translate: ''Ho finito di leggere il libro.''', '["I finished reading the book.","I finished to read the book.","I finished read the book.","I finish reading the book."]', NULL, 0, '''Finish'' is followed by a gerund.', NULL, 'Traduzione', 'B1', 'Gerunds vs Infinitives', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q421', 'Translate: ''Lui ha deciso di studiare all''estero.''', '["He decided to study abroad.","He decided studying abroad.","He decided study abroad.","He decides to study abroad."]', NULL, 0, '''Decide'' is followed by the infinitive.', NULL, 'Traduzione', 'B1', 'Gerunds vs Infinitives', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q422', 'Are you planning _____ to the party?', '["to go","going","go","went"]', NULL, 0, '''Plan'' takes the infinitive with ''to''.', NULL, 'Grammatica', 'B1', 'Gerunds vs Infinitives', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q423', 'I miss _____ near the sea.', '["living","to live","live","lived"]', NULL, 0, '''Miss'' is followed by the gerund.', NULL, 'Grammatica', 'B1', 'Gerunds vs Infinitives', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q424', 'Translate: ''Non mi dispiace alzarmi presto.''', '["I don''t mind getting up early.","I don''t mind to get up early.","I don''t mind get up early.","I not mind getting up early."]', NULL, 0, '''Don''t mind'' takes the gerund.', NULL, 'Traduzione', 'B1', 'Gerunds vs Infinitives', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q425', 'Translate: ''Loro vogliono comprare una casa nuova.''', '["They want to buy a new house.","They want buying a new house.","They want buy a new house.","They want to buying a new house."]', NULL, 0, '''Want'' is followed by the infinitive.', NULL, 'Traduzione', 'B1', 'Gerunds vs Infinitives', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q426', 'He offered _____ for dinner.', '["to pay","paying","pay","paid"]', NULL, 0, '''Offer'' takes the infinitive with ''to''.', NULL, 'Grammatica', 'B1', 'Gerunds vs Infinitives', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q427', 'Keep _____ until you reach the station.', '["walking","to walk","walk","walked"]', NULL, 0, '''Keep'' is followed by the gerund.', NULL, 'Grammatica', 'B1', 'Gerunds vs Infinitives', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q428', 'I would like _____ a pizza.', '["to order","ordering","order","ordered"]', NULL, 0, '''Would like'' is followed by the infinitive with ''to''.', NULL, 'Grammatica', 'B1', 'Gerunds vs Infinitives', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q429', 'Stop _____ noise!', '["making","to make","make","made"]', NULL, 0, 'Stop + -ing means to quit an action.', NULL, 'Grammatica', 'B1', 'Gerunds vs Infinitives', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q430', 'I remembered _____ the door before leaving.', '["to lock","to locking","lock","locked"]', NULL, 0, 'Remember + to-infinitive means ''not forget to do something'' (''I remembered to lock the door''); after ''to'' we always use the base form, never -ing.', NULL, 'Grammatica', 'B1', 'Gerunds vs Infinitives', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q431', 'If I _____ more time, I would learn a new language.', '["had","have","would have","will have"]', NULL, 0, 'Second Conditional: If + past simple.', NULL, 'Grammatica', 'B1', 'Second Conditional', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q432', 'What would you do if you _____ a ghost?', '["saw","see","would see","will see"]', NULL, 0, 'Second Conditional: If + past simple.', NULL, 'Grammatica', 'B1', 'Second Conditional', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q433', 'If she _____ closer, we would see her more often.', '["lived","lives","would live","will live"]', NULL, 0, 'Second Conditional: If + past simple.', NULL, 'Grammatica', 'B1', 'Second Conditional', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q434', 'Translate: ''Se fossi ricco, viaggerei per il mondo.''', '["If I were rich, I would travel the world.","If I am rich, I will travel the world.","If I was rich, I travel the world.","If I would be rich, I traveled the world."]', NULL, 0, 'Second Conditional uses ''were'' for all persons and ''would + verb''.', NULL, 'Traduzione', 'B1', 'Second Conditional', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q435', 'Translate: ''Se lei sapesse la verità, si arrabbierebbe.''', '["If she knew the truth, she would be angry.","If she knows the truth, she will be angry.","If she would know the truth, she was angry.","If she knew the truth, she will be angry."]', NULL, 0, 'Past simple in the if-clause, would in the main clause.', NULL, 'Traduzione', 'B1', 'Second Conditional', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q436', 'If they _____ so much pizza, they wouldn''t feel sick.', '["didn''t eat","don''t eat","wouldn''t eat","won''t eat"]', NULL, 0, 'Negative if-clause in Second Conditional uses ''didn''t + verb''.', NULL, 'Grammatica', 'B1', 'Second Conditional', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q437', 'I would buy that car if it _____ cheaper.', '["were","is","would be","will be"]', NULL, 0, '''were'' is used for the verb ''to be'' in the Second Conditional.', NULL, 'Grammatica', 'B1', 'Second Conditional', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q438', 'If you _____ more, you would pass the exam.', '["studied","study","would study","will study"]', NULL, 0, 'Second Conditional: If + Past Simple (''studied''), would + base verb, for an unreal or unlikely present situation.', NULL, 'Grammatica', 'B1', 'Second Conditional', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q439', 'Translate: ''Non andrei lì se fossi in te.''', '["I wouldn''t go there if I were you.","I won''t go there if I am you.","I didn''t go there if I were you.","I don''t go there if I was you."]', NULL, 0, '''If I were you'' is standard for giving advice.', NULL, 'Traduzione', 'B1', 'Second Conditional', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q440', 'Translate: ''Se avessimo una macchina, potremmo andare in montagna.''', '["If we had a car, we could go to the mountains.","If we have a car, we can go to the mountains.","If we had a car, we will go to the mountains.","If we would have a car, we went to the mountains."]', NULL, 0, '''could'' is the conditional form of ''can''.', NULL, 'Traduzione', 'B1', 'Second Conditional', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q441', 'If he _____ his job, he would travel more.', '["quit","quits","will quit","would quit"]', NULL, 0, 'Past simple of ''quit'' is ''quit''.', NULL, 'Grammatica', 'B1', 'Second Conditional', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q442', 'She would be happier if she _____ a better job.', '["found","finds","will find","would find"]', NULL, 0, 'Past simple in the if-clause.', NULL, 'Grammatica', 'B1', 'Second Conditional', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q443', 'If it _____ snowing, we could go for a walk.', '["stopped","stops","will stop","would stop"]', NULL, 0, 'Past simple of stop is stopped.', NULL, 'Grammatica', 'B1', 'Second Conditional', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q444', 'I _____ you if I knew the answer.', '["would tell","tell","told","will tell"]', NULL, 0, 'Main clause requires ''would + verb''.', NULL, 'Grammatica', 'B1', 'Second Conditional', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q445', 'If we _____ in a big city, we would use public transport.', '["lived","live","will live","would live"]', NULL, 0, 'Past simple in the if-clause.', NULL, 'Grammatica', 'B1', 'Second Conditional', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q446', 'Translate: ''Se parlassi francese, mi trasferirei a Parigi.''', '["If I spoke French, I would move to Paris.","If I speak French, I will move to Paris.","If I would speak French, I moved to Paris.","If I spoke French, I will move to Paris."]', NULL, 0, 'If + past simple, would + infinitive.', NULL, 'Traduzione', 'B1', 'Second Conditional', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q447', 'If I _____ earlier, I would have caught the train.', '["had woken up","woke up","would wake up","have woken up"]', NULL, 0, 'Third Conditional uses If + Past Perfect.', NULL, 'Grammatica', 'B1', 'Third Conditional', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q448', 'She would have passed if she _____ harder.', '["had studied","studied","would study","has studied"]', NULL, 0, 'If + Past Perfect (had + past participle).', NULL, 'Grammatica', 'B1', 'Third Conditional', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q449', 'If we had known, we _____ you.', '["would have helped","would help","helped","had helped"]', NULL, 0, 'Main clause uses ''would have + past participle''.', NULL, 'Grammatica', 'B1', 'Third Conditional', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q450', 'Translate: ''Se fossi andato a letto presto, non sarei stato stanco.''', '["If I had gone to bed early, I wouldn''t have been tired.","If I went to bed early, I wouldn''t be tired.","If I had gone to bed early, I wasn''t tired.","If I would go to bed early, I wouldn''t have been tired."]', NULL, 0, 'Third conditional talks about impossible past situations.', NULL, 'Traduzione', 'B1', 'Third Conditional', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q451', 'Translate: ''Se avesse piovuto, saremmo rimasti a casa.''', '["If it had rained, we would have stayed at home.","If it rained, we would stay at home.","If it had rained, we stayed at home.","If it rains, we will stay at home."]', NULL, 0, 'If + Past Perfect, would have + past participle.', NULL, 'Traduzione', 'B1', 'Third Conditional', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q452', 'If he had driven carefully, he _____ the accident.', '["wouldn''t have had","wouldn''t have","didn''t have","hadn''t had"]', NULL, 0, 'Main clause negative is ''wouldn''t have + past participle''.', NULL, 'Grammatica', 'B1', 'Third Conditional', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q453', 'They would have won if they _____ better.', '["had played","played","would play","have played"]', NULL, 0, 'If clause uses Past Perfect.', NULL, 'Grammatica', 'B1', 'Third Conditional', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q454', 'If I _____ the umbrella, I would have gotten wet.', '["hadn''t taken","didn''t take","wouldn''t take","haven''t taken"]', NULL, 0, 'Negative if-clause uses ''hadn''t + past participle''.', NULL, 'Grammatica', 'B1', 'Third Conditional', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q455', 'Translate: ''Cosa avresti fatto se lo avessi saputo?''', '["What would you have done if you had known?","What would you do if you knew?","What did you do if you had known?","What have you done if you knew?"]', NULL, 0, 'Interrogative third conditional structure.', NULL, 'Traduzione', 'B1', 'Third Conditional', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q456', 'Translate: ''Se avessi visto il messaggio, ti avrei risposto.''', '["If I had seen the message, I would have replied.","If I saw the message, I would reply.","If I would have seen the message, I replied.","If I had seen the message, I had replied."]', NULL, 0, 'Standard third conditional structure.', NULL, 'Traduzione', 'B1', 'Third Conditional', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q457', 'If she _____ the directions, she wouldn''t have gotten lost.', '["had followed","followed","would follow","has followed"]', NULL, 0, 'Third Conditional: If + Past Perfect (''had followed''), would have + past participle, for an imaginary situation in the past.', NULL, 'Grammatica', 'B1', 'Third Conditional', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q458', 'I _____ to the party if they had invited me.', '["would have gone","would go","went","had gone"]', NULL, 0, 'Main clause requires ''would have + past participle''.', NULL, 'Grammatica', 'B1', 'Third Conditional', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q459', 'If it _____ so cold, we would have gone swimming.', '["hadn''t been","wasn''t","wouldn''t be","hasn''t been"]', NULL, 0, 'Negative Past Perfect.', NULL, 'Grammatica', 'B1', 'Third Conditional', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q460', 'We would have bought the house if it _____ cheaper.', '["had been","was","would be","has been"]', NULL, 0, 'Past Perfect of ''to be'' is ''had been''.', NULL, 'Grammatica', 'B1', 'Third Conditional', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q461', 'If you had asked me, I _____ yes.', '["would have said","would say","said","had said"]', NULL, 0, 'Main clause uses ''would have + past participle''.', NULL, 'Grammatica', 'B1', 'Third Conditional', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q462', 'Translate: ''Sarebbe venuta se avesse avuto tempo.''', '["She would have come if she had had time.","She would come if she had time.","She came if she had had time.","She would have came if she had time."]', NULL, 0, '''had had'' is the Past Perfect of ''have''.', NULL, 'Traduzione', 'B1', 'Third Conditional', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q463', 'The Mona Lisa _____ by Leonardo da Vinci.', '["was painted","painted","is painted","paints"]', NULL, 0, 'Past Simple passive: was + past participle.', NULL, 'Grammatica', 'B1', 'Passive Voice', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q464', 'English _____ in many countries around the world.', '["is spoken","speaks","was spoken","has spoken"]', NULL, 0, 'Present Simple passive for facts.', NULL, 'Grammatica', 'B1', 'Passive Voice', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q465', 'My car _____ at the moment.', '["is being repaired","is repairing","repairs","has repaired"]', NULL, 0, 'Present Continuous passive for ongoing actions.', NULL, 'Grammatica', 'B1', 'Passive Voice', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q466', 'Translate: ''Il libro è stato scritto nel 1990.''', '["The book was written in 1990.","The book is written in 1990.","The book wrote in 1990.","The book has been written in 1990."]', NULL, 0, 'Past Simple passive for a completed action in the past.', NULL, 'Traduzione', 'B1', 'Passive Voice', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q467', 'Translate: ''La stanza viene pulita ogni giorno.''', '["The room is cleaned every day.","The room was cleaned every day.","The room is being cleaned every day.","The room cleans every day."]', NULL, 0, 'Present Simple passive for routines.', NULL, 'Traduzione', 'B1', 'Passive Voice', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q468', 'A new supermarket _____ in our town next year.', '["will be built","will build","is built","was built"]', NULL, 0, 'Future passive: will be + past participle.', NULL, 'Grammatica', 'B1', 'Passive Voice', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q469', 'The thieves _____ by the police yesterday.', '["were caught","caught","are caught","have caught"]', NULL, 0, 'Past Simple passive (plural).', NULL, 'Grammatica', 'B1', 'Passive Voice', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q470', 'This picture _____ by my grandfather.', '["was taken","took","is taken","takes"]', NULL, 0, 'Past Simple passive.', NULL, 'Grammatica', 'B1', 'Passive Voice', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q471', 'Translate: ''I biglietti sono già stati venduti.''', '["The tickets have already been sold.","The tickets are already sold.","The tickets were already sold.","The tickets already sold."]', NULL, 0, 'Present Perfect passive: have been + past participle.', NULL, 'Traduzione', 'B1', 'Passive Voice', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q472', 'Translate: ''Il problema deve essere risolto subito.''', '["The problem must be solved immediately.","The problem must solve immediately.","The problem has to solve immediately.","The problem must been solved immediately."]', NULL, 0, 'Modal passive: modal + be + past participle.', NULL, 'Traduzione', 'B1', 'Passive Voice', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q473', 'The emails _____ every morning at 8 am.', '["are sent","send","were sent","have sent"]', NULL, 0, 'Present Simple passive for routines.', NULL, 'Grammatica', 'B1', 'Passive Voice', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q474', 'The dinner _____ when the guests arrived.', '["was being cooked","was cooking","is cooked","has been cooked"]', NULL, 0, 'Past Continuous passive for interrupted past actions.', NULL, 'Grammatica', 'B1', 'Passive Voice', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q475', 'The bridge _____ in 2005.', '["was built","built","is built","has built"]', NULL, 0, 'Past Simple passive.', NULL, 'Grammatica', 'B1', 'Passive Voice', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q476', 'All the cake _____ by the children before I came.', '["had been eaten","had eaten","was eating","is eaten"]', NULL, 0, 'Past Perfect passive.', NULL, 'Grammatica', 'B1', 'Passive Voice', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q477', 'The keys _____ on the table yesterday.', '["were left","left","are left","have left"]', NULL, 0, 'Past Simple passive.', NULL, 'Grammatica', 'B1', 'Passive Voice', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q478', 'Translate: ''La mia bicicletta è stata rubata ieri.''', '["My bicycle was stolen yesterday.","My bicycle is stolen yesterday.","My bicycle has been stolen yesterday.","My bicycle stole yesterday."]', NULL, 0, 'Past Simple passive.', NULL, 'Traduzione', 'B1', 'Passive Voice', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q479', 'He said, ''I like apples.'' -> He said that he _____ apples.', '["liked","likes","like","had liked"]', NULL, 0, 'Present simple shifts to past simple.', NULL, 'Grammatica', 'B1', 'Reported Speech', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q480', 'She said, ''I am watching TV.'' -> She said that she _____ TV.', '["was watching","is watching","watches","had watched"]', NULL, 0, 'Present continuous shifts to past continuous.', NULL, 'Grammatica', 'B1', 'Reported Speech', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q481', '''I will go,'' he said. -> He said that he _____ go.', '["would","will","can","could"]', NULL, 0, '''Will'' shifts to ''would''.', NULL, 'Grammatica', 'B1', 'Reported Speech', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q482', 'Translate: ''Mi ha detto che era stanco.''', '["He told me that he was tired.","He said me that he was tired.","He told to me that he was tired.","He said that he is tired."]', NULL, 0, '''Tell'' must be followed by an object pronoun (me).', NULL, 'Traduzione', 'B1', 'Reported Speech', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q483', 'Translate: ''Lei disse che non sapeva la risposta.''', '["She said that she didn''t know the answer.","She told that she didn''t know the answer.","She said that she doesn''t know the answer.","She told me that she hasn''t known the answer."]', NULL, 0, '''Said'' doesn''t need an object pronoun.', NULL, 'Traduzione', 'B1', 'Reported Speech', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q484', '''I have finished,'' she said. -> She said that she _____ finished.', '["had","has","was","is"]', NULL, 0, 'Present perfect shifts to past perfect.', NULL, 'Grammatica', 'B1', 'Reported Speech', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q485', 'He asked me where I _____.', '["lived","live","did I live","do I live"]', NULL, 0, 'Reported questions use affirmative word order, without ''do/did''.', NULL, 'Grammatica', 'B1', 'Reported Speech', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q486', 'She asked if I _____ coffee.', '["liked","like","did I like","do I like"]', NULL, 0, 'Yes/No reported questions use ''if'' + affirmative past simple.', NULL, 'Grammatica', 'B1', 'Reported Speech', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q487', 'Translate: ''Mi ha chiesto se volessi venire.''', '["He asked me if I wanted to come.","He asked me do I want to come.","He said me if I wanted to come.","He told me if I wanted to come."]', NULL, 0, 'Reported questions use ''ask'' + if + subject + verb.', NULL, 'Traduzione', 'B1', 'Reported Speech', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q488', 'Translate: ''Ha detto che avrebbe chiamato più tardi.''', '["He said that he would call later.","He said that he will call later.","He told that he would call later.","He said that he would called later."]', NULL, 0, '''Would'' is the reported version of ''will''.', NULL, 'Traduzione', 'B1', 'Reported Speech', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q489', '''Don''t touch that!'' he said. -> He told me _____ that.', '["not to touch","don''t touch","didn''t touch","not touch"]', NULL, 0, 'Reported negative commands use ''not to + infinitive''.', NULL, 'Grammatica', 'B1', 'Reported Speech', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q490', '''Open the door,'' she said. -> She told me _____ the door.', '["to open","open","opened","opening"]', NULL, 0, 'Reported commands use ''to + infinitive''.', NULL, 'Grammatica', 'B1', 'Reported Speech', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q491', 'He said, ''I can swim.'' -> He said that he _____ swim.', '["could","can","would","might"]', NULL, 0, '''Can'' shifts to ''could''.', NULL, 'Grammatica', 'B1', 'Reported Speech', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q492', 'She asked, ''Are you okay?'' -> She asked me _____ okay.', '["if I was","if was I","are you","if you are"]', NULL, 0, 'Reported questions use subject + verb order.', NULL, 'Grammatica', 'B1', 'Reported Speech', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q493', '''I must go,'' he said. -> He said that he _____ go.', '["had to","musts","must to","have to"]', NULL, 0, '''Must'' usually shifts to ''had to'' in reported speech; ''must'' never takes -s or ''to'', and ''have to'' would need to become ''had to''.', NULL, 'Grammatica', 'B1', 'Reported Speech', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q494', 'Translate: ''Mi ha consigliato di studiare.''', '["He advised me to study.","He advised to study.","He said me to study.","He told to me to study."]', NULL, 0, 'Advise takes object + to-infinitive.', NULL, 'Traduzione', 'B1', 'Reported Speech', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q495', 'By the time we arrived, the movie _____.', '["had started","started","has started","starts"]', NULL, 0, 'Past Perfect is used for the action that happened first in the past.', NULL, 'Grammatica', 'B1', 'Past Perfect', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q496', 'I realized I _____ my keys at home.', '["had left","left","have left","leave"]', NULL, 0, 'You left them before you realized it.', NULL, 'Grammatica', 'B1', 'Past Perfect', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q497', 'She was tired because she _____ all day.', '["had worked","worked","has worked","works"]', NULL, 0, 'Action leading up to a past state.', NULL, 'Grammatica', 'B1', 'Past Perfect', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q498', 'Translate: ''Avevo appena finito di mangiare quando ha bussato.''', '["I had just finished eating when he knocked.","I just finished eating when he knocked.","I have just finished eating when he knocked.","I had just finished to eat when he knocked."]', NULL, 0, 'Past perfect + just for an action completed moments before another past action.', NULL, 'Traduzione', 'B1', 'Past Perfect', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q499', 'Translate: ''Non avevo mai visto quel film prima di ieri.''', '["I had never seen that movie before yesterday.","I never saw that movie before yesterday.","I have never seen that movie before yesterday.","I hadn''t never seen that movie before yesterday."]', NULL, 0, 'Past perfect + never for experiences before a specific past point.', NULL, 'Traduzione', 'B1', 'Past Perfect', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q501', 'By the time the manager called, they _____ the project.', '["had finished","finished","have finished","finish"]', NULL, 0, '''By the time'' + a past event requires the Past Perfect (''had finished'') for the action completed before that moment.', NULL, 'Grammatica', 'B1', 'Past Perfect', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q502', 'He didn''t want to eat because he _____ lunch.', '["had already had","already had","has already had","already has"]', NULL, 0, 'The Past Perfect (''had already had'') shows the earlier action: he had lunch first, so later he wasn''t hungry.', NULL, 'Grammatica', 'B1', 'Past Perfect', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q503', 'Translate: ''Ero arrabbiato perché avevo perso il portafoglio.''', '["I was angry because I had lost my wallet.","I was angry because I lost my wallet.","I was angry because I have lost my wallet.","I was angry because I had lose my wallet."]', NULL, 0, 'Cause and effect in the past.', NULL, 'Traduzione', 'B1', 'Past Perfect', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q504', 'Translate: ''Avevano vissuto lì per dieci anni prima di trasferirsi.''', '["They had lived there for ten years before moving.","They lived there for ten years before moving.","They have lived there for ten years before moving.","They had lived there since ten years before moving."]', NULL, 0, 'Duration before a past action.', NULL, 'Traduzione', 'B1', 'Past Perfect', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q505', 'I _____ him before that day.', '["had never met","never met","have never met","never meet"]', NULL, 0, 'Experience before a past event.', NULL, 'Grammatica', 'B1', 'Past Perfect', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q506', 'The grass was yellow because it _____ all summer.', '["hadn''t rained","didn''t rain","hasn''t rained","doesn''t rain"]', NULL, 0, 'Negative past perfect.', NULL, 'Grammatica', 'B1', 'Past Perfect', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q507', 'She passed the test because she _____ hard.', '["had studied","had study","has studied","studies"]', NULL, 0, 'The Past Perfect (''had'' + past participle ''studied'') shows that the studying happened before she passed the test; ''had study'' has no past participle and ''has studied/studies'' don''t fit a past story.', NULL, 'Grammatica', 'B1', 'Past Perfect', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q508', 'I couldn''t open the door because I _____ the key.', '["had lost","lost","have lost","lose"]', NULL, 0, 'Lost the key before trying to open.', NULL, 'Grammatica', 'B1', 'Past Perfect', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q509', 'By the time I woke up, everyone _____.', '["had gone","went","has gone","goes"]', NULL, 0, '''By the time'' is a strong trigger for the Past Perfect.', NULL, 'Grammatica', 'B1', 'Past Perfect', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q510', 'Translate: ''La festa era già finita quando siamo arrivati.''', '["The party had already ended when we arrived.","The party already ended when we arrived.","The party has already ended when we arrived.","The party had already ending when we arrived."]', NULL, 0, 'Past Perfect with ''already''.', NULL, 'Traduzione', 'B1', 'Past Perfect', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q511', 'I _____ eat a lot of chocolate, but now I don''t.', '["used to","use to","was used to","am used to"]', NULL, 0, 'Past habit that is no longer true.', NULL, 'Grammatica', 'B1', 'Used to', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q512', '_____ you use to play video games when you were a kid?', '["Did","Do","Were","Are"]', NULL, 0, 'Interrogative form requires ''Did'' + ''use to'' (without d).', NULL, 'Grammatica', 'B1', 'Used to', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q513', 'She _____ like coffee, but now she loves it.', '["didn''t use to","didn''t used to","doesn''t use to","wasn''t used to"]', NULL, 0, 'Negative form is ''didn''t use to''.', NULL, 'Grammatica', 'B1', 'Used to', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q514', 'Translate: ''Abitavamo a Londra quando ero piccolo.''', '["We used to live in London when I was a kid.","We used to lived in London when I was a kid.","We are used to live in London when I was a kid.","We use to live in London when I was a kid."]', NULL, 0, 'Used to + infinitive.', NULL, 'Traduzione', 'B1', 'Used to', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q515', 'Translate: ''Non fumava, ma ora fuma un pacchetto al giorno.''', '["He didn''t use to smoke, but now he smokes a pack a day.","He didn''t used to smoke, but now he smokes a pack a day.","He wasn''t used to smoke, but now he smokes a pack a day.","He hasn''t used to smoke, but now he smokes a pack a day."]', NULL, 0, 'The negative of ''used to'' is ''didn''t use to'' (no -d after ''didn''t'', because ''did'' already shows the past); ''un pacchetto al giorno'' is ''a pack a day''.', NULL, 'Traduzione', 'B1', 'Used to', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q516', 'There _____ be a park here, but now there is a supermarket.', '["used to","use to","was","is"]', NULL, 0, '''There used to be'' describes a past state.', NULL, 'Grammatica', 'B1', 'Used to', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q517', 'I _____ have a dog, but he died last year.', '["used to","use to","was used to","am used to"]', NULL, 0, '''Used to'' + base verb describes a past state that is no longer true (I had a dog, but now I don''t).', NULL, 'Grammatica', 'B1', 'Used to', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q518', 'What did you _____ do on Sundays?', '["use to","used to","use","used"]', NULL, 0, 'After ''did'', use the base form ''use to''.', NULL, 'Grammatica', 'B1', 'Used to', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q519', 'Translate: ''Andavamo al mare ogni estate.''', '["We used to go to the sea every summer.","We use to go to the sea every summer.","We were used to go to the sea every summer.","We had gone to the sea every summer."]', NULL, 0, '''Used to'' + base verb describes a repeated action in the past that doesn''t happen now (''andavamo'' = we used to go).', NULL, 'Traduzione', 'B1', 'Used to', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q520', 'Translate: ''Aveva i capelli lunghi, vero?''', '["She used to have long hair, didn''t she?","She used to have long hair, doesn''t she?","She used to had long hair, didn''t she?","She use to have long hair, didn''t she?"]', NULL, 0, 'Question tag for used to is ''didn''t''.', NULL, 'Traduzione', 'B1', 'Used to', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q521', 'He _____ be so grumpy when he was younger.', '["didn''t use to","didn''t used to","wasn''t use to","not used to"]', NULL, 0, 'Negative past habit.', NULL, 'Grammatica', 'B1', 'Used to', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q522', 'We _____ walk to school every day.', '["used to","use to","were used to","are used to"]', NULL, 0, '''Used to'' + base verb describes a past habit or routine; ''be used to'' means ''essere abituato'' and is a different structure.', NULL, 'Grammatica', 'B1', 'Used to', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q523', 'Did she _____ work in a bank?', '["use to","used to","use","used"]', NULL, 0, 'Question form drops the ''d'' in use.', NULL, 'Grammatica', 'B1', 'Used to', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q524', 'I _____ think that spiders were insects.', '["used to","use to","was used to","am used to"]', NULL, 0, 'Past belief that changed.', NULL, 'Grammatica', 'B1', 'Used to', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q525', 'They _____ travel a lot before they had children.', '["used to","use to","were used to","are used to"]', NULL, 0, '''Used to'' + base verb describes a past habit that has stopped (they travelled a lot before having children).', NULL, 'Grammatica', 'B1', 'Used to', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q526', 'Translate: ''Prima non mi piaceva la verdura.''', '["I didn''t use to like vegetables.","I didn''t used to like vegetables.","I wasn''t used to like vegetables.","I hadn''t used to like vegetables."]', NULL, 0, 'Negative past state.', NULL, 'Traduzione', 'B1', 'Used to', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q527', 'It''s a beautiful day, _____?', '["isn''t it","is it","does it","doesn''t it"]', NULL, 0, 'Affirmative statement -> negative tag.', NULL, 'Grammatica', 'B1', 'Question Tags', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q528', 'You don''t like coffee, _____?', '["do you","don''t you","are you","aren''t you"]', NULL, 0, 'Negative statement -> affirmative tag.', NULL, 'Grammatica', 'B1', 'Question Tags', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q529', 'She went to Paris, _____?', '["didn''t she","did she","doesn''t she","wasn''t she"]', NULL, 0, 'Past simple affirmative -> didn''t.', NULL, 'Grammatica', 'B1', 'Question Tags', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q530', 'Translate: ''Siete italiani, vero?''', '["You are Italian, aren''t you?","You are Italian, isn''t it?","You are Italian, don''t you?","You are Italian, are you?"]', NULL, 0, 'The tag must match the subject (you) and auxiliary (are).', NULL, 'Traduzione', 'B1', 'Question Tags', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q531', 'Translate: ''Non hai visto il film, vero?''', '["You haven''t seen the movie, have you?","You haven''t seen the movie, haven''t you?","You didn''t see the movie, have you?","You haven''t seen the movie, did you?"]', NULL, 0, 'Present perfect negative -> affirmative ''have'' tag.', NULL, 'Traduzione', 'B1', 'Question Tags', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q532', 'They have finished the project, _____?', '["haven''t they","have they","didn''t they","don''t they"]', NULL, 0, 'Present perfect affirmative -> haven''t.', NULL, 'Grammatica', 'B1', 'Question Tags', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q533', 'He can speak Spanish, _____?', '["can''t he","can he","doesn''t he","isn''t he"]', NULL, 0, 'Modal ''can'' -> can''t.', NULL, 'Grammatica', 'B1', 'Question Tags', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q534', 'You will come to the party, _____?', '["won''t you","will you","don''t you","aren''t you"]', NULL, 0, 'Future ''will'' -> won''t.', NULL, 'Grammatica', 'B1', 'Question Tags', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q535', 'Translate: ''Fa freddo oggi, no?''', '["It''s cold today, isn''t it?","It''s cold today, is it?","It''s cold today, doesn''t it?","It''s cold today, wasn''t it?"]', NULL, 0, 'Verb to be -> isn''t.', NULL, 'Traduzione', 'B1', 'Question Tags', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q536', 'Translate: ''Lui non sa nuotare, vero?''', '["He can''t swim, can he?","He can''t swim, can''t he?","He doesn''t know to swim, doesn''t he?","He can''t swim, does he?"]', NULL, 0, 'Negative can''t -> affirmative can.', NULL, 'Traduzione', 'B1', 'Question Tags', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q537', 'We should leave now, _____?', '["shouldn''t we","should we","don''t we","aren''t we"]', NULL, 0, 'Modal ''should'' -> shouldn''t.', NULL, 'Grammatica', 'B1', 'Question Tags', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q538', 'She was at home, _____?', '["wasn''t she","was she","didn''t she","isn''t she"]', NULL, 0, 'Past simple to be -> wasn''t.', NULL, 'Grammatica', 'B1', 'Question Tags', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q539', 'I am right, _____?', '["aren''t I","am not I","don''t I","isn''t I"]', NULL, 0, '''I am'' always takes the tag ''aren''t I?''.', NULL, 'Grammatica', 'B1', 'Question Tags', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q540', 'Let''s go for a walk, _____?', '["shall we","will we","do we","are we"]', NULL, 0, '''Let''s'' always takes the tag ''shall we?''.', NULL, 'Grammatica', 'B1', 'Question Tags', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q541', 'You wouldn''t do that, _____?', '["would you","wouldn''t you","do you","did you"]', NULL, 0, 'Negative wouldn''t -> affirmative would.', NULL, 'Grammatica', 'B1', 'Question Tags', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q542', 'Translate: ''Tua sorella vive qui, vero?''', '["Your sister lives here, doesn''t she?","Your sister lives here, isn''t she?","Your sister lives here, doesn''t it?","Your sister lives here, don''t she?"]', NULL, 0, 'Present simple action verb -> doesn''t.', NULL, 'Traduzione', 'B1', 'Question Tags', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q543', 'They have been traveling all day. They _____ be tired.', '["must","can''t","might","should"]', NULL, 0, 'Strong logical deduction.', NULL, 'Grammatica', 'B1', 'Modals of Deduction', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q544', 'He just ate a huge meal. He _____ be hungry.', '["can''t","must","might","could"]', NULL, 0, 'Negative logical deduction (impossible).', NULL, 'Grammatica', 'B1', 'Modals of Deduction', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q545', 'I can''t find my phone. It _____ be in the car, but I''m not sure.', '["might","must","can''t","should"]', NULL, 0, 'Possibility without certainty.', NULL, 'Grammatica', 'B1', 'Modals of Deduction', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q546', 'Translate: ''Deve essere tardi, è già buio.''', '["It must be late, it''s already dark.","It can be late, it''s already dark.","It may to be late, it''s already dark.","It should be late, it''s already dark."]', NULL, 0, '''Must'' + base verb is used for a logical deduction based on evidence (it''s already dark); modals are never followed by ''to''.', NULL, 'Traduzione', 'B1', 'Modals of Deduction', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q547', 'Translate: ''Non può essere vero!''', '["It can''t be true!","It mustn''t be true!","It shouldn''t be true!","It might not be true!"]', NULL, 0, 'Can''t is the opposite of must for deductions.', NULL, 'Traduzione', 'B1', 'Modals of Deduction', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q548', 'That _____ be John''s car. His car is blue, not red.', '["can''t","must","might","could"]', NULL, 0, 'Logical impossibility.', NULL, 'Grammatica', 'B1', 'Modals of Deduction', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q549', 'You''ve been working since 6 AM. You _____ be exhausted!', '["must","can''t","might","can"]', NULL, 0, '''Must'' + base verb expresses a strong, logical certainty based on evidence (you''ve been working since 6 AM).', NULL, 'Grammatica', 'B1', 'Modals of Deduction', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q550', 'Take an umbrella. It _____ rain later.', '["might","must","can''t","should"]', NULL, 0, '''Might'' + base verb expresses a possibility in the future: it may rain later, but we aren''t sure.', NULL, 'Grammatica', 'B1', 'Modals of Deduction', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q551', 'Translate: ''Potrebbe piovere più tardi.''', '["It might rain later.","It must rain later.","It can rain later.","It will rain later."]', NULL, 0, '''Might'' or ''could'' indicates possibility.', NULL, 'Traduzione', 'B1', 'Modals of Deduction', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q552', 'Translate: ''Quello dev''essere il tuo nuovo capo.''', '["That must be your new boss.","That can be your new boss.","That should be your new boss.","That must to be your new boss."]', NULL, 0, '''Must'' + base verb (''must be'') expresses a logical deduction we are almost sure about (''dev''essere''); modals are never followed by ''to''.', NULL, 'Traduzione', 'B1', 'Modals of Deduction', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q553', 'She speaks perfect French, has a French passport and her parents live in Paris. She _____ be from France.', '["must","can''t","might","should"]', NULL, 0, 'When the evidence makes us almost certain, we use ''must'' + base verb for a positive deduction; ''might'' would express only a possibility.', NULL, 'Grammatica', 'B1', 'Modals of Deduction', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q554', 'He is holding a cinema ticket for tonight''s film. He _____ be going to the cinema.', '["must","can''t","might","should"]', NULL, 0, '''Must be'' + -ing makes a strong deduction about what someone is doing now or soon, based on clear evidence (a cinema ticket for tonight).', NULL, 'Grammatica', 'B1', 'Modals of Deduction', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q555', 'It''s 3 a.m., the lights are out and the house is silent. They _____ be asleep.', '["must","can''t","might","won''t"]', NULL, 0, 'At 3 a.m. with the lights out and total silence we are almost sure, so we use ''must'' + base verb for a certain deduction.', NULL, 'Grammatica', 'B1', 'Modals of Deduction', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q556', 'She _____ be at home, but I haven''t checked.', '["could","must","can''t","won''t"]', NULL, 0, 'Possibility (similar to might).', NULL, 'Grammatica', 'B1', 'Modals of Deduction', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q557', 'This _____ be the right way. The map says to go left.', '["can''t","must","might","could"]', NULL, 0, 'Logical impossibility.', NULL, 'Grammatica', 'B1', 'Modals of Deduction', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q558', 'Translate: ''Questa non può essere la casa giusta.''', '["This can''t be the right house.","This mustn''t be the right house.","This shouldn''t be the right house.","This wouldn''t be the right house."]', NULL, 0, 'Can''t for negative deduction.', NULL, 'Traduzione', 'B1', 'Modals of Deduction', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q559', 'Complete the sentence: ''Don''t forget _____ the front door before you go to bed.''', '["to lock","locking","lock","locked"]', NULL, 0, '''Forget + to-infinitive'' refers to a duty or future action that must not be forgotten (Ricordati di fare qualcosa).', NULL, 'Grammatica', 'B1', 'Gerunds vs Infinitives', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q560', 'Complete the sentence: ''I will never forget _____ the Colosseum for the very first time.''', '["seeing","to see","see","saw"]', NULL, 0, '''Forget + -ing'' refers to the memory of a past event: ''I will never forget seeing the Colosseum'' = non dimenticherò mai la prima volta che ho visto il Colosseo.', NULL, 'Grammatica', 'B1', 'Gerunds vs Infinitives', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q561', 'Complete the sentence: ''On the road trip, we stopped _____ a coffee and stretch our legs.''', '["to have","having","have","had"]', NULL, 0, '''Stop + to-infinitive'' expresses purpose (ci siamo fermati per prendere un caffè).', NULL, 'Grammatica', 'B1', 'Gerunds vs Infinitives', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q562', 'Complete the sentence: ''The doctor told him that he must stop _____ immediately for his health.''', '["smoking","to smoke","smoke","smoked"]', NULL, 0, '''Stop + -ing'' means to quit an action or habit completely (smettere di fumare).', NULL, 'Grammatica', 'B1', 'Gerunds vs Infinitives', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q563', 'Complete the sentence: ''If the app keeps crashing, try _____ your smartphone.''', '["restarting","to restart","restart","restarted"]', NULL, 0, '''Try + -ing'' means doing something as an experiment, to see if it solves a problem (prova a riavviare); ''try + to-infinitive'' means making an effort to do something difficult.', NULL, 'Grammatica', 'B1', 'Gerunds vs Infinitives', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q564', 'Complete the sentence: ''I tried _____ the heavy wardrobe, but it was impossible alone.''', '["to lift","lifting","lift","lifted"]', NULL, 0, '''Try + to-infinitive'' means to make a physical or mental effort to achieve something difficult.', NULL, 'Grammatica', 'B1', 'Gerunds vs Infinitives', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q565', 'Complete the sentence: ''Look at the kitchen floor! It really needs _____.''', '["cleaning","to clean","clean","cleaned"]', NULL, 0, '''Need + -ing'' has a passive meaning (= needs to be cleaned). Classic CEFR B1 structure!', NULL, 'Grammatica', 'B1', 'Gerunds vs Infinitives', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q566', 'Complete the sentence: ''I am really looking forward to _____ you at the conference next week.''', '["meeting","meet","to meet","met"]', NULL, 0, 'In ''look forward to'', ''to'' is a preposition, so it must be followed by a gerund (-ing form).', NULL, 'Grammatica', 'B1', 'Gerunds vs Infinitives', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q567', 'Translate: ''Non riesco a fare a meno di ridere quando sento quella barzelletta.''', '["I can''t help laughing when I hear that joke.","I can''t help to laugh when I hear that joke.","I can''t stop to laugh when I hear that joke.","I can''t avoid to laugh when I hear that joke."]', NULL, 0, '''Can''t help + -ing'' is a fixed idiom meaning unable to prevent yourself from doing something.', NULL, 'Traduzione', 'B1', 'Gerunds vs Infinitives', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q568', 'Translate: ''È inutile piangere sul latte versato.''', '["It''s no use crying over spilled milk.","It''s no use to cry over spilled milk.","It''s not useful crying on spilled milk.","It has no use to cry on spilled milk."]', NULL, 0, '''It''s no use + -ing'' is an idiomatic structure followed by the gerund.', NULL, 'Traduzione', 'B1', 'Gerunds vs Infinitives', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q569', 'Complete the sentence: ''Could you please give me _____ about the flight schedule?''', '["some information","an information","some informations","many informations"]', NULL, 0, '''Information'' is an uncountable noun in English: it never takes an ''s'' and cannot be preceded by ''an''.', NULL, 'Grammatica', 'B1', 'Quantifiers', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q570', 'Complete the sentence: ''My grandfather gave me a very useful _____ before my interview.''', '["piece of advice","advice","advices","piece of advices"]', NULL, 0, '''Advice'' is uncountable. To refer to a single unit, use ''a piece of advice''.', NULL, 'Grammatica', 'B1', 'Quantifiers', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q571', 'Complete the sentence: ''The news _____ so surprising that nobody believed it at first.''', '["was","were","are","have been"]', NULL, 0, 'Even though ''news'' ends in ''s'', it is a singular uncountable noun and takes a singular verb (''was'').', NULL, 'Grammatica', 'B1', 'Quantifiers', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q572', 'Complete the sentence: ''All the furniture in their new apartment _____ made of solid oak.''', '["is","are","were","have been"]', NULL, 0, '''Furniture'' is uncountable in English and always takes a singular verb (''is'').', NULL, 'Grammatica', 'B1', 'Quantifiers', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q573', 'Complete the sentence: ''How _____ luggage are you planning to take on the flight?''', '["much","many","few","a few"]', NULL, 0, '''Luggage'' (or baggage) is uncountable, so it is quantified with ''much'' (or ''a lot of'').', NULL, 'Grammatica', 'B1', 'Quantifiers', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q574', 'Complete the sentence: ''The police _____ investigating the cause of the fire.''', '["are","is","was","has been"]', NULL, 0, '''Police'' is a plural collective noun with no ''s'', but it ALWAYS takes a plural verb (''are / were'').', NULL, 'Grammatica', 'B1', 'Quantifiers', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q575', 'Translate: ''Non ho molti compiti per domani.''', '["I don''t have much homework for tomorrow.","I don''t have many homeworks for tomorrow.","I don''t have many homework for tomorrow.","I haven''t much homeworks for tomorrow."]', NULL, 0, '''Homework'' is uncountable in English, so we use ''much homework'' and never ''homeworks''.', NULL, 'Traduzione', 'B1', 'Quantifiers', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q577', 'Complete the sentence: ''Let''s take a short break, _____?''', '["shall we","will we","don''t we","aren''t we"]', NULL, 0, 'Suggestions starting with ''Let''s'' always take the question tag ''shall we?''.', NULL, 'Grammatica', 'B1', 'Question Tags', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q578', 'Complete the sentence: ''Close the window, _____?''', '["will you","do you","don''t you","shall you"]', NULL, 0, 'Imperative sentences (requests/commands) take ''will you?'' (or ''won''t you?'') as question tag.', NULL, 'Grammatica', 'B1', 'Question Tags', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q579', 'Complete the sentence: ''She never drinks alcohol, _____?''', '["does she","doesn''t she","is she","isn''t she"]', NULL, 0, 'Words with negative meaning (never, seldom, rarely) make the clause negative, requiring an affirmative tag (''does she?'').', NULL, 'Grammatica', 'B1', 'Question Tags', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q580', 'Complete the sentence: ''Nobody phoned while I was away, _____?''', '["did they","didn''t they","did he","didn''t he"]', NULL, 0, '''Nobody'' has negative meaning (so the tag is positive) and uses the plural pronoun ''they'' (''did they?'').', NULL, 'Grammatica', 'B1', 'Question Tags', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q581', 'Complete the sentence: ''Nothing went wrong during the test, _____?''', '["did it","didn''t it","did they","was it"]', NULL, 0, '''Nothing'' is negative (requiring positive tag) and refers to a thing, represented by ''it'' (''did it?'').', NULL, 'Grammatica', 'B1', 'Question Tags', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q582', 'Complete the sentence: ''Everybody is ready for the presentation, _____?''', '["aren''t they","isn''t he","isn''t it","are they"]', NULL, 0, '''Everybody'' takes a singular verb in the main clause (''is''), but takes ''they'' with a plural verb in the tag (''aren''t they?'').', NULL, 'Grammatica', 'B1', 'Question Tags', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q583', 'Complete the sentence: ''I will call you as soon as I _____ at the airport.''', '["arrive","will arrive","am arriving","arrived"]', NULL, 0, 'In time clauses introduced by ''as soon as'', ''when'', ''until'', etc., we use the Present Simple, NOT ''will''.', NULL, 'Grammatica', 'B1', 'Present Simple', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q584', 'Complete the sentence: ''We will stay inside until the heavy rain _____.''', '["stops","will stop","stopped","is stopping"]', NULL, 0, 'After ''until'', English uses the Present Simple for future references (never ''will'').', NULL, 'Grammatica', 'B1', 'Present Simple', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q585', 'Complete the sentence: ''You won''t pass your driving test unless you _____ every day.''', '["practice","don''t practice","will practice","won''t practice"]', NULL, 0, '''Unless'' means ''if not'', so it already contains a negative meaning. Do not use double negatives or ''will''.', NULL, 'Grammatica', 'B1', 'First Conditional', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q586', 'Complete the sentence: ''Take an umbrella with you in case it _____ later.''', '["rains","will rain","rained","is raining"]', NULL, 0, '''In case'' (per precauzione) is followed by the Present Simple when referring to the future.', NULL, 'Grammatica', 'B1', 'Present Simple', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q587', 'Translate: ''Te lo dirò non appena lo saprò.''', '["I will tell you as soon as I know.","I will tell you as soon as I will know.","I tell you as soon as I will know.","I will tell to you as soon as I know."]', NULL, 0, 'Time clause rule: ''as soon as I know'' (Present Simple, never ''will know'').', NULL, 'Traduzione', 'B1', 'Present Simple', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q588', 'Complete the sentence: ''I _____ what you mean, but I still disagree with your conclusion.''', '["understand","am understanding","have understand","understanding"]', NULL, 0, '''Understand'' is a stative verb (mental state) and is not normally used in the continuous form.', NULL, 'Grammatica', 'B1', 'Present Simple', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q589', 'Complete the sentence: ''Please don''t disturb Marco right now; he _____ lunch with a client.''', '["is having","has","have","had"]', NULL, 0, 'When ''have'' means eating/drinking (''having lunch''), it is a dynamic action and CAN be continuous!', NULL, 'Grammatica', 'B1', 'Present Continuous', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q590', 'Complete the sentence: ''Be quiet for a minute! I _____ about how to solve this math problem.''', '["am thinking","think","thinks","thought"]', NULL, 0, '''Think'' in the continuous form (''am thinking'') refers to an active mental process at this moment.', NULL, 'Grammatica', 'B1', 'Present Continuous', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q591', 'Complete the sentence: ''I _____ that learning English is essential for your career.''', '["think","am thinking","thinking","thought"]', NULL, 0, 'When ''think'' expresses an opinion (''I think that...''), it is stative and cannot be continuous.', NULL, 'Grammatica', 'B1', 'Present Simple', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q592', 'Complete the sentence: ''This delicious pasta dish _____ of fresh tomatoes and basil.''', '["tastes","is tasting","taste","was tasting"]', NULL, 0, '''Taste'' describing the flavor of food is a stative verb (takes Present Simple).', NULL, 'Grammatica', 'B1', 'Present Simple', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q593', 'Complete the sentence: ''For _____ details regarding the hotel booking, contact customer support.''', '["further","farther","farthest","more far"]', NULL, 0, '''Further'' means ''additional/more'' (figurative), while ''farther'' strictly refers to physical distance.', NULL, 'Grammatica', 'B1', 'Comparatives and Superlatives', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q594', 'Complete the sentence: ''Today the traffic is _____ than it was yesterday morning.''', '["heavier","more heavy","more heavier","heaviest"]', NULL, 0, 'Two-syllable adjectives ending in ''-y'' change ''-y'' to ''-ier'' (heavy -> heavier).', NULL, 'Grammatica', 'B1', 'Comparatives and Superlatives', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q595', 'Complete the sentence: ''The new laptop is great, but it is not _____ fast as I expected.''', '["as","so much","more","like"]', NULL, 0, 'Equality comparatives in the negative use ''not as ... as'' (or ''not so ... as'').', NULL, 'Grammatica', 'B1', 'Comparatives and Superlatives', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q596', 'Complete the sentence: ''The _____ you practice speaking, the _____ confident you will feel.''', '["more / more","most / most","better / better","much / much"]', NULL, 0, 'The double comparative structure ''The more..., the more...'' expresses proportional change.', NULL, 'Grammatica', 'B1', 'Comparatives and Superlatives', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q597', 'Translate: ''Mio fratello maggiore vive a Londra.''', '["My elder brother lives in London.","My elder brother living in London.","My more old brother lives in London.","My eldest brother live in London."]', NULL, 0, '''Elder'' (like the more common ''older'') describes the older of two family members and is used only before a noun (''my elder brother''). With ''brother'' the verb needs the third person -s (''lives'').', NULL, 'Traduzione', 'B1', 'Comparatives and Superlatives', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q598', 'Complete the sentence: ''When I moved to the UK, it took me a long time to get used to _____ on the left.''', '["driving","drive","drove","driven"]', NULL, 0, '''Get used to + -ing'' means the process of becoming accustomed to something.', NULL, 'Grammatica', 'B1', 'Used to', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q599', 'Complete the sentence: ''I am a nurse, so I am used to _____ night shifts.''', '["working","work","worked","to work"]', NULL, 0, '''Be used to + -ing'' means to be already accustomed/familiar with a situation.', NULL, 'Grammatica', 'B1', 'Used to', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q600', 'Complete the sentence: ''I _____ drink coffee when I was younger, but now I drink three cups a day.''', '["didn''t use to","didn''t used to","not used to","wasn''t used to"]', NULL, 0, 'The negative of ''used to'' is ''didn''t use to'': ''did'' already carries the past, so ''use'' has no -d. ''Wasn''t used to'' means ''non ero abituato'' and needs a noun or -ing form.', NULL, 'Grammatica', 'B1', 'Used to', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q601', 'Translate: ''Ti sei abituato al clima freddo?''', '["Have you got used to the cold weather?","Did you use to the cold weather?","Have you used to the cold weather?","Did you get use to cold weather?"]', NULL, 0, '''Get used to + noun'' expresses becoming accustomed to a condition (''Have you got used to...?''); ''use to'' without ''get'' or ''be'' cannot be followed by a noun.', NULL, 'Traduzione', 'B1', 'Used to', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q602', 'Complete the sentence: ''Venice, _____ is famous for its canals, attracts millions of tourists every year.''', '["which","that","where","what"]', NULL, 0, 'In non-defining relative clauses (between commas), you must use ''which'' for things, NEVER ''that''.', NULL, 'Grammatica', 'B1', 'Relative Clauses', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q603', 'Complete the sentence: ''Mr. Davis, _____ you met yesterday at the reception, is our new director.''', '["whom","which","that","whose"]', NULL, 0, 'In non-defining clauses for people as object, ''whom'' (or ''who'') is used; ''that'' is strictly prohibited between commas.', NULL, 'Grammatica', 'B1', 'Relative Clauses', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q604', 'Complete the sentence: ''That is the student _____ backpack was accidentally left in the classroom.''', '["whose","who''s","which","that''s"]', NULL, 0, '''Whose'' is the relative pronoun used to indicate possession.', NULL, 'Grammatica', 'B1', 'Relative Clauses', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q605', 'Complete the sentence: ''The hotel _____ we stayed at during our holiday was right on the beach.''', '["that","where","what","whose"]', NULL, 0, 'Because the preposition ''at'' is at the end (''stayed at''), we use ''that'' or ''which'', NOT ''where''.', NULL, 'Grammatica', 'B1', 'Relative Clauses', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q606', 'Translate: ''Londra, che è la capitale del Regno Unito, ha molti musei gratuiti.''', '["London, which is the capital of the UK, has many free museums.","London, that is the capital of the UK, has many free museums.","London, where is the capital of the UK, has many free museums.","London, what is the capital of the UK, has many free museums."]', NULL, 0, 'In non-defining relative clauses (between commas), we must use ''which'' for things, never ''that''; ''where'' and ''what'' are not relative pronouns for a subject here.', NULL, 'Traduzione', 'B1', 'Relative Clauses', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q612', 'I ...... English Food', '["dcn''t like","don''t like","not like","liked not"]', NULL, 1, 'Nel Present Simple la forma negativa per la prima persona singolare ''I'' è ''don''t like''.', NULL, 'Grammatica', 'A1', 'Present Simple', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q615', 'Monday is the ...... day of the week', '["worst","baddest","worse","badest"]', NULL, 0, 'Il superlativo relativo irregolare dell''aggettivo ''bad'' è ''worst'' (''the worst day'').', NULL, 'Grammatica', 'A2', 'Comparatives and Superlatives', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q616', 'Can I offer you ...... to drink?', '["something","some","somewhat","any"]', NULL, 0, 'Nelle offerte (''Can I offer you...'') si usa di solito il pronome ''something'' seguito da ''to drink''; ''some'' e ''any'' da soli sono determinanti e ''somewhat'' significa ''un po''''.', NULL, 'Grammatica', 'A2', 'Quantifiers', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q617', 'No sugar please. I like coffee ...... sugar.', '["without","and","with","no"]', NULL, 0, '''Without'' è la preposizione che significa ''senza'', coerentemente con ''No sugar please''.', NULL, 'Grammatica', 'A1', 'Present Simple', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q619', 'She ...... meet her friends tomorrow.', '["is","do","will","does"]', NULL, 2, '''Will'' esprime un''azione futura ed è seguito direttamente dalla forma base del verbo (''will meet'').', NULL, 'Grammatica', 'A2', 'Present Simple', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q620', '- choose the correct sentence -', '["Look! It''s raining","Look! it''s raining","Look! it raining","Look! it raning"]', NULL, 0, 'Dopo il punto esclamativo la frase successiva inizia con lettera maiuscola (''It''s'') e la forma del Present Continuous è ''is raining''.', NULL, 'Grammatica', 'A1', 'Present Continuous', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q621', '...... any milk in the fridge', '["There is","There isn''t","There aren''t","There are"]', NULL, 1, '''Milk'' è non numerabile (richiede la forma singolare) e nelle frasi negative si usa ''any'': ''There isn''t any milk''.', NULL, 'Grammatica', 'A1', 'There is / There are', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q628', 'Steven works ...... Microsoft.', '["for","on","in","to"]', NULL, 0, 'Si dice ''work for'' seguito dall''azienda o dal datore di lavoro (''works for Microsoft'').', NULL, 'Grammatica', 'A1', 'Prepositions of Place', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q629', 'I don''t like ...... make-up.', '["of Sara","Sara''s","Saras","Sara"]', NULL, 1, 'Si usa il genitivo sassone con apostrofo e ''s'' per indicare il possesso riferito a una persona: ''Sara''s make-up''.', NULL, 'Grammatica', 'A1', 'Possessive S', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q630', '...... have you studied English?', '["How far","How much","How long","How many"]', NULL, 2, '''How long'' è la domanda utilizzata per domandare la durata nel tempo (''Da quanto tempo'').', NULL, 'Grammatica', 'A2', 'Questions and Origins', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q631', 'How ...... people came to the party?', '["few","much","many","any"]', NULL, 2, 'Con i sostantivi numerabili plurali come ''people'' si utilizza ''How many''.', NULL, 'Grammatica', 'A1', 'Quantifiers', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q632', 'James ...... English very well.', '["cans speak","can speak","can speaks","can to speak"]', NULL, 1, 'Il verbo modale ''can'' è invariabile (senza ''-s'' alla terza persona) ed è seguito dalla forma base senza ''to'' (''can speak'').', NULL, 'Grammatica', 'A1', 'Modals of Ability and Permission', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q635', 'New York is......than London.', '["more moderner","more modern","modernest","modern"]', NULL, 1, 'L''aggettivo ''modern'' forma il comparativo di maggioranza con ''more'' (''more modern than'').', NULL, 'Grammatica', 'A2', 'Comparatives and Superlatives', 0);
